/* Règles partagées de la démo. Toute autorisation entre comptes exige un serveur. */
const RULES0291=(()=>{'use strict';const DAY=86400000,TARGETS=[250,300,350,400,450,500,550,600,650,700,800],HERO_SIZES={Commun:.8,Rare:.90,Épique:.95,Légendaire:1};
const tierIndex=t=>({Commun:0,Rare:1,Épique:2,Légendaire:3})[t]??0;
function heroQuote(base,tier,from){if(!Number.isInteger(from)||from<1||from>=20)throw Error('Niveau invalide');return {...base,diamonds:20+10*tierIndex(tier)+Math.round(20*(from-1)/18),durationSeconds:300+Math.round(900*(from-1)/18)};}
function donationQuote(id,from,progress=0){if(!['yield','construction','selection','exclusion'].includes(id)||!Number.isInteger(from)||from<0)throw Error('Technologie inconnue');const target=TARGETS[Math.min(10,from)],max=id==='selection'?1:id==='exclusion'?3:10,n=Math.min(from,max-1),first=n===0?23000:49000+(n-1)*14000,cap=n===0?49000:63000+(n-1)*14000,rate=['yield','construction'].includes(id)?.25:.5;return {id,from,to:Math.min(max,from+1),target,amount:Math.round((first+(cap-first)*Math.min(progress,target-1)/Math.max(1,target-1))*rate),resource:['yield','selection'].includes(id)?'gold':'elixir',maxed:from>=max};}
const acceleration=remaining=>remaining>0?Math.max(1,Math.ceil(remaining/3600000*5)):0;
function overflow(wallet,reward,cap){return Object.fromEntries(['gold','elixir'].map(k=>[k,Math.max(0,(wallet[k]||0)+(reward[k]||0)-(typeof cap==='number'?cap:cap[k]))]));}
function rankClans(rows){let sorted=rows.map(r=>({...r})).sort((a,b)=>(b.wins||0)-(a.wins||0)||(b.stars||0)-(a.stars||0)||(b.destruction||0)-(a.destruction||0)||(a.duration||0)-(b.duration||0));let last=null,rank=0;return sorted.map((r,i)=>{let key=JSON.stringify([r.wins||0,r.stars||0,r.destruction||0,r.duration||0]);if(key!==last)rank=i+1;last=key;return {...r,rank};});}
function tournamentPrize(rank,capacity){let gold=rank===1?400000:rank<=3?280000:rank<=10?200000:rank<=20?100000:20000,rate=rank===1?.4:rank<=3?.3:rank<=10?.2:rank<=20?.15:.1;return {treasury:{gold,elixir:gold},personal:{gold:Math.floor(capacity*rate),elixir:Math.floor(capacity*rate)},rate};}
function tournamentCredit(state,eventId,rank,capacity){if(!eventId)throw Error('Tournoi requis');let s=structuredClone(state);s.receipts??=[];if(s.receipts.includes(eventId))return {...s,repeated:true};let p=tournamentPrize(rank,capacity);s.treasury??={gold:0,elixir:0};s.treasury.gold+=p.treasury.gold;s.treasury.elixir+=p.treasury.elixir;s.pendingPersonal??=[];s.pendingPersonal.push({eventId,...p.personal});s.receipts.push(eventId);return s;}
function linkReferral(links,parent,child){if(!parent||!child||parent===child)throw Error('Auto-parrainage interdit');if(links.some(l=>l.parent===parent||l.child===child))throw Error('Parrain ou filleul déjà associé');let current=parent,seen=new Set([child]);while(current){if(seen.has(current))throw Error('Cycle interdit');seen.add(current);current=links.find(l=>l.child===current)?.parent;}return [...links,{parent,child,createdAt:Date.now(),qualified:false}];}
function referralBonus(order,links,now=Date.now()){if(!order.verified||order.status!=='credited'||order.refunded||now<order.at+DAY)return null;let l=links.find(l=>l.parent===order.playerId||l.child===order.playerId);if(!l)return null;return {id:'referral:'+order.id,playerId:l.parent===order.playerId?l.child:l.parent,diamonds:Math.floor(order.baseDiamonds*.05)};}
function hash(s){let n=2166136261;for(let c of s){n^=c.charCodeAt(0);n=Math.imul(n,16777619)}return n>>>0;}
function monthlyOffer(month){let seed=hash('blabox-global:'+month),day=3+seed%13,start=Date.parse(month+'-'+String(day).padStart(2,'0')+'T00:00:00Z');return {id:'monthly:'+month,activeMonth:seed%100<25,start,end:start+6*DAY,rate:.2};}
function activePromotion(player,now=Date.now()){let first=player.firstOfferAt;if(first&&!(player.purchaseCount>0)&&now<first+6*DAY)return {id:'first',rate:.5,until:first+6*DAY};let month=new Date(now).toISOString().slice(0,7),o=monthlyOffer(month);if(o.activeMonth&&now>=o.start&&now<o.end&&!(first&&now<first+6*DAY))return {...o,until:o.end};return null;}
function purchaseAmount(base,promo){let bonus=Math.floor(base*(promo?.rate||0));return {base,bonus,total:base+bonus};}
const PERMISSIONS={admin:['reports.read','messages.hide','players.warn','sanctions.temporary','gifts.small','photos.review','purchases.inspect','audit.read'],creator:['*']};
function authorize(role,permission){return role==='creator'||PERMISSIONS[role]?.includes(permission)||false;}
function sanction(role,{scope,minutes,permanent=false,targetRole='player'}){if(role!=='creator'&&role!=='admin')throw Error('Rôle non autorisé');if(targetRole==='creator'||targetRole==='admin'&&role!=='creator')throw Error('Cible protégée');if(role==='admin'&&(permanent||minutes>60||!['chat','game'].includes(scope)))throw Error('Sanction réservée au créateur');if(!permanent&&(!Number.isInteger(minutes)||minutes<1))throw Error('Durée invalide');return true;}
return {DAY,TARGETS,HERO_SIZES,heroQuote,donationQuote,acceleration,overflow,rankClans,tournamentPrize,tournamentCredit,linkReferral,referralBonus,monthlyOffer,activePromotion,purchaseAmount,authorize,sanction,PERMISSIONS};})();
if(typeof module!=='undefined')module.exports=RULES0291;

