/* Référence courante. Les opérations distantes restent à valider côté serveur. */
const RULES030=(()=>{'use strict';const DAY=86400000,INVITE_TTL=4*DAY,ENERGY_PRICE=81300;
const COLORS=['#257bb0','#bc3f43','#7650a5','#37805b','#d69b28','#dc7135','#263a61','#e9e1ca','#269c9c','#713d65'];
const clanCapacity=tech=>20+Math.min(8,Object.values(tech||{}).reduce((n,v)=>n+Math.max(0,Math.floor(Number(v)||0)),0));
function quantity(n){if(!Number.isSafeInteger(n)||n<1||n>9999)throw Error('Choisis une quantité entre 1 et 9 999.');return n;}
function monthsAfter(at,n=4){let d=new Date(at),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);let max=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,max));return +d;}
function clanExpired(members,now=Date.now(),lastHumanActivity=0){let humans=(members||[]).filter(m=>!m.bot);return humans.length?humans.every(m=>monthsAfter(m.lastSeenAt||m.joinedAt||0)<now):monthsAfter(lastHumanActivity)<now;}
function createBots(clanId,level=1,at=Date.now()){return ['Borin','Liora','Kaël','Naya'].map((name,i)=>({id:clanId+':bot:'+i,name,bot:true,mainLevel:level,clanId,joinedAt:at,lastSeenAt:at,incomeDay:(()=>{let p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(at).map(p=>[p.type,p.value]));return p.year+'-'+p.month+'-'+p.day;})()}));}
function botIncome(clan,members,day){let c=structuredClone(clan),rows=structuredClone(members),total=0;c.botIncome??={};for(let m of rows.filter(m=>m.bot)){let start=c.botIncome[m.id]||m.incomeDay||day,days=Math.max(0,Math.floor((Date.parse(day)-Date.parse(start))/DAY));if(days){let amount=days*10000;c.treasury.gold+=amount;c.treasury.elixir+=amount;total+=amount;c.botIncome[m.id]=day;}}return {clan:c,members:rows,total};}
function catalog(base){return base.filter(p=>!['mana-5','mana-40','health-100'].includes(p.id)).map(p=>p.id==='shield-1d'?{...p,resource:'gold',secondaryResource:'elixir',secondaryPrice:p.price,secondaryWholesale:p.wholesale}:p).concat([{id:'energy-refill',name:'Recharge · 1 énergie',asset:'item:energy',resource:'gold',secondaryResource:'elixir',price:ENERGY_PRICE,secondaryPrice:ENERGY_PRICE,wholesale:ENERGY_PRICE,secondaryWholesale:ENERGY_PRICE,item:'energy-refill',noDiscount:true,fullReturn:true}]);}
function trade(player,clan,item,count,{stock=false,discount=0,commandId,now=Date.now()}={}){quantity(count);if(!commandId||!item||player.clanId!==clan.id)throw Error('Transaction de clan invalide.');if(clan.ledger?.some(r=>r.id===commandId)){return {player:structuredClone(player),clan:structuredClone(clan),repeated:true};}if(stock&&!['chief','admin'].includes(player.clanRole))throw Error('Responsables de l’alliance uniquement.');let p=structuredClone(player),c=structuredClone(clan),rate=stock||item.noDiscount?0:Math.max(0,Math.min(.2,discount)),unitGold=Math.floor((stock?item.wholesale:item.price)*(1-rate)),unitSecond=Math.floor((stock?item.secondaryWholesale:item.secondaryPrice||0)*(1-rate)),total=unitGold*count,second=unitSecond*count,wallet=stock?c.treasury:p.wallet;
if(!stock&&item.id==='energy-refill'){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);p.energyPurchases0301??={};if((p.energyPurchases0301[day]||0)+count>5)throw Error('Limite de 5 énergies achetées par jour.');p.energyPurchases0301[day]=(p.energyPurchases0301[day]||0)+count;}
if(!stock&&(c.stock?.[item.id]||0)<count)throw Error('Stock insuffisant.');if(wallet[item.resource]<total||item.secondaryResource&&wallet[item.secondaryResource]<second)throw Error(stock?'Trésorerie insuffisante.':'Ressources insuffisantes.');if(!stock&&item.hero&&count!==1)throw Error('Un seul héros par achat.');if(!stock&&item.hero&&p.heroes?.[item.hero]?.unlocked)throw Error('Ce héros est déjà dans ta collection.');wallet[item.resource]-=total;if(item.secondaryResource)wallet[item.secondaryResource]-=second;c.stock??={};c.stock[item.id]=(c.stock[item.id]||0)+(stock?count:-count);
if(!stock){let credit=item.fullReturn?total:item.id==='clan-banner'?total:Math.floor(total*.85);c.treasury[item.resource]+=credit;if(item.secondaryResource)c.treasury[item.secondaryResource]+=item.fullReturn?second:Math.floor(second*.85);p.inventory??={};p.vials??={};p.heroes??={};p.decorations??=[];if(item.item)p.inventory[item.item]=(p.inventory[item.item]||0)+count;if(item.vial)p.vials[item.vial]=(p.vials[item.vial]||0)+count;if(item.hero)p.heroes[item.hero]={unlocked:true,level:1};if(item.decoration&&!p.decorations.includes(item.decoration))p.decorations.push(item.decoration);}
let receipt={id:commandId,playerId:p.id,kind:stock?'restock':'sale',item:item.id,count,resource:item.resource,amount:total,secondaryResource:item.secondaryResource,secondaryAmount:second,discount:rate,at:now};(c.ledger??=[]).push(receipt);if(!stock)(p.clanPurchases??=[]).push(receipt);return {player:p,clan:c};}
function profileChange(profile,id,day,wallet){if(!id)throw Error('Portrait invalide.');if(profile.hero===id)return {profile,wallet,repeated:true};if(profile.changedDay===day)throw Error('Ton portrait a déjà été changé aujourd’hui.');if(wallet.diamonds<1)throw Error('Un diamant est nécessaire.');return {profile:{...profile,hero:id,changedDay:day},wallet:{...wallet,diamonds:wallet.diamonds-1}};}
function giftPurchase({base,promoRate=0,gift=false}){if(!Number.isSafeInteger(base)||base<1)throw Error("Montant invalide.");let total=base+Math.floor(base*promoRate);return {base,bonus:total-base,total,senderBonus:gift?Math.floor(total*.15):0,firstGiftBonus:gift?Math.floor(total*.5):0};}
const ADMIN_PERMISSIONS=['sanctions.temporary','referrals.read','referrals.verify','referrals.manage'];
return {DAY,INVITE_TTL,ENERGY_PRICE,COLORS,clanCapacity,quantity,monthsAfter,clanExpired,createBots,botIncome,catalog,trade,profileChange,giftPurchase,ADMIN_PERMISSIONS};})();
