 if((s.unlockedTroops?!s.unlockedTroops.includes(id):s.level<troop.unlock)||!Number.isInteger(s.researchBuildingLevel)||s.researchBuildingLevel<1)throw Error('Monstre ou Centre de recherche verrouillé.');
