 const l=blankCastle(level),reserve=[];
 for(const list of ['defenses','garrisons','traps'])for(const i of old[list]||[])reserve.push({list,item:{...i},preferred:Math.min(l.floors-1,Math.max(0,Math.round((16-i.y)/16*(l.floors-1))))});
