// Planches partagées : chargement à la demande, cache mémoire limité et cache disque facultatif.
const ASSETS029=(()=>{const images=new Map();let dbPromise=null,loaded=0,evicted=0;const stats={requests:0,diskHits:0,errors:0};
function db(){if(!/^https?:$/.test(location.protocol)||!window.indexedDB)return Promise.resolve(null);return dbPromise??=new Promise(resolve=>{try{const r=indexedDB.open('blabox-medias-029',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);}catch{resolve(null);}});}
async function cached(file){let d=await db();if(!d)return null;return new Promise(resolve=>{try{let r=d.transaction('images').objectStore('images').get(file);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null);}catch{resolve(null);}});}
async function remember(file,blob){let d=await db();if(!d)return;try{let tx=d.transaction('images','readwrite');tx.objectStore('images').put(blob,file);tx.onerror=()=>{};}catch{}}
function get(file){let r=images.get(file);if(r){r.used=performance.now();return r;}stats.requests++;r={image:new Image(),ready:false,used:performance.now(),promise:null,url:null};images.set(file,r);r.promise=(async()=>{let blob=await cached(file);if(blob)stats.diskHits++;if(!blob&&/^https?:$/.test(location.protocol)){try{let response=await fetch(file);if(!response.ok)throw Error(response.status);blob=await response.blob();remember(file,blob);}catch{}}if(blob){r.url=URL.createObjectURL(blob);r.image.src=r.url;}else r.image.src=file;await r.image.decode();r.ready=true;loaded++;trim();return r.image;})().catch(e=>{stats.errors++;r.failed=true;console.warn('Planche indisponible',file);return null;});return r;}
function trim(){if(images.size<=20)return;for(let [key,r]of [...images].sort((a,b)=>a[1].used-b[1].used)){if(images.size<=16)break;if(!r.ready)continue;if(r.url)URL.revokeObjectURL(r.url);r.image.src='';images.delete(key);evicted++;}}
setInterval(trim,5000);return {get,inspect:()=>({...stats,decoded:images.size,loaded,evicted,maxIdle:16})};})();

