/* Atelier local réservé au créateur. Aucune identité interne ne doit être publiée. */
const BOTLAB0301=(()=>{'use strict';const flags=['FR','GB','US','DE','CA','JP','BR'];const names=['Iron Falcons','Silver Wardens','Golden Keepers','Storm Ravens','Crimson Shields','Royal Wolves','Emerald Watch','Azure Knights','Dawn Sentinels','Frost Guardians','Amber Lions','Steel Eagles','Scarlet Legion','Sapphire Oath','Oak Defenders','Thunder Crown','Ivory Blades','Shadow Bastion','Phoenix Order','Winter Vanguard','Sunward Guard'];
function seed(){const alliances=names.map((name,i)=>({id:'war-alliance-'+i,name,level:11+Math.floor(i/3),obvious:false}));for(let i=0;i<10;i++)alliances.push({id:'fun-alliance-'+i,name:'BOT · '+['Potato Knights','Sleepy Turnips','Wobbly Ducks','Tiny Socks','Cheese Brigade','Banana Guards','Silly Spoons','Lazy Pebbles','Snoring Frogs','Muddy Boots'][i],level:5+i%4,obvious:true});let bots=[];for(let i=0;i<30;i++)bots.push(make('pillage-'+i,5+i%16,'pillage',i,alliances));for(let lv=11;lv<=17;lv++)for(let i=0;i<10;i++)bots.push(make('war-'+lv+'-'+i,lv,'war',(lv-11)*10+i,alliances));for(let a=0;a<10;a++)for(let i=0;i<15;i++){let b=make('fun-'+a+'-'+i,2+(i+a)%5,'fun',a*15+i,alliances);b.difficulty='easy';b.identities=b.identities.map((v,j)=>({name:'BOT '+['Biscuit','Potato','Puddle'][j]+' '+(i+1),allianceId:'fun-alliance-'+a}));bots.push(b);}return {schema:1,published:false,updatedAt:Date.now(),alliances,bots};}
function make(id,level,group,i,alliances){return {id,level,group,flag:flags[i%flags.length],difficulty:['easy','normal','hard'][i%3],seed:i+1,reservePercent:50,minePercent:35,reservePerHour:1000,minePerHour:700,refillAt:Date.now(),identities:Array.from({length:3},(_,j)=>({name:['Aldric','Brom','Corwin','Darian','Elric','Finn','Gareth','Haldor','Ivor','Jorin'][i%10]+' '+['Oak','Frost','Vale'][j]+' '+(i+1),allianceId:group==='war'?'war-alliance-'+((level-11)*3+j):null}))};}
function validate(lab){if(!lab||lab.schema!==1||!Array.isArray(lab.bots)||lab.bots.length>400||!Array.isArray(lab.alliances)||lab.alliances.length>50)throw Error('Atelier invalide.');let x=structuredClone(lab),ids=new Set();for(let a of x.alliances){if(!a.id||ids.has(a.id)||typeof a.name!=='string'||!a.name.trim()||a.name.length>40)throw Error('Alliance invalide.');ids.add(a.id);}ids=new Set();for(let b of x.bots){if(!b.id||ids.has(b.id)||!Number.isInteger(b.level)||b.level<1||b.level>20||!['pillage','war','fun'].includes(b.group)||!['easy','normal','hard'].includes(b.difficulty)||!flags.includes(b.flag))throw Error('Personnage invalide.');ids.add(b.id);for(let k of ['reservePercent','minePercent'])if(!Number.isFinite(b[k])||b[k]<0||b[k]>100)throw Error('Remplissage invalide.');for(let k of ['reservePerHour','minePerHour'])if(!Number.isSafeInteger(b[k])||b[k]<0||b[k]>100000000)throw Error('Production invalide.');if(!Number.isInteger(b.seed)||b.seed<0||!Number.isFinite(b.refillAt))throw Error('Génération invalide.');if(!Array.isArray(b.identities)||b.identities.length!==3)throw Error('Trois identités requises.');for(let n of b.identities)if(typeof n.name!=='string'||!n.name.trim()||n.name.length>40||n.allianceId&&!x.alliances.some(a=>a.id===n.allianceId))throw Error('Identité invalide.');}x.updatedAt=Date.now();return x;}
function layout(b){const stage=(b.seed%8)+(b.difficulty==='hard'?24:b.difficulty==='normal'?8:0),l=PreviewGame.stageMap(stage,b.level);if(b.difficulty==='easy'){l.defenses=l.defenses.slice(0,2);l.traps=[];}if(b.difficulty==='hard'){for(let d of l.defenses)d.level=b.level;}return PreviewGame.cleanTestLayout020(l);}
function resources(b,now=Date.now()){const cap=PreviewGame.storageCapacity(b.level),hours=Math.max(0,now-b.refillAt)/3600000,mineCap=PreviewGame.v06Production(b.level)*10;return {reserveGold:Math.min(cap,Math.floor(cap*b.reservePercent/100+hours*b.reservePerHour)),reserveElixir:Math.min(cap,Math.floor(cap*b.reservePercent/100+hours*b.reservePerHour)),mineGold:Math.min(mineCap,Math.floor(mineCap*b.minePercent/100+hours*b.minePerHour)),mineElixir:Math.min(mineCap,Math.floor(mineCap*b.minePercent/100+hours*b.minePerHour))};}
return {seed,validate,layout,resources,flags};})();

