  for(const h of heroes)if(h.active)spellNames[h.id]=h.abilities?[h.skill]:[];
  const currentOpen=open,currentClose=close,currentModal=renderModal,currentAction=action,currentArmy=army,currentProducts=products,currentHUD=renderHUD,currentSettings=settings;
  const currentRoles={chief:'Chef',admin:'Administrateur',chosen:'Sentinelle',random:'Tirage au sort',member:'Membre'};
  const currentId=prefix=>prefix+':'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2));
  const flagEmoji=code=>[...code].map(c=>String.fromCodePoint(127397+c.charCodeAt(0))).join('');
  const clanAccount=()=>({id:state.id,clanId:state.clanId,clanRole:state.clanRole,wallet:state.wallet,lastClanDonationAt:state.lastClanDonationAt,clanDonationAt:state.clanDonationAt||{},inventory:state.inventory,vials:state.vials,energyPurchases0301:state.energyPurchases0301,heroes:Object.fromEntries([...state.ownedHeroes].map(id=>[id,{unlocked:true}])),decorations:state.clanDecorations||[],clanPurchases:state.clanPurchases||[]});
  function acceptClan(r){state.wallet=r.player.wallet;state.lastClanDonationAt=r.player.lastClanDonationAt;state.clanDonationAt=r.player.clanDonationAt||{};state.inventory=r.player.inventory;state.vials=r.player.vials;state.clanPurchases=r.player.clanPurchases||[];state.clanDecorations=r.player.decorations||[];state.clanData=r.clan;state.clanTech=r.clan.tech;state.clanTreasury=r.clan.treasury;renderHUD();renderModal();}
  function fullMapLayer(){let el=$('#full-map-layer');if(!el){el=document.createElement('section');el.id='full-map-layer';el.hidden=true;$('#stage').append(el);}return el;}
  open=function(page,tab=null){if(['campaign','war'].includes(page)){if(page==='war'&&!state.clan){toast('Rejoins un clan pour accéder à la guerre.');return;}state.mapPage=page;state.modal=page;state.tab=tab;$('#modal-layer').hidden=true;renderFullMap(true);return;}return currentOpen(page,tab);};
