  let castleInitialScroll=false;
  fitCastle=function(){const zone=$('#castle-zone'),floors=layout.floors+(!state.battle&&state.jobs.some(j=>j.floorJob)?1:0),width=layout.slots*CW()+104,height=floors*fh()+82,fit=Math.min(1,(zone.clientWidth||1050)/width);zone.style.alignItems='flex-start';const castle=$('#castle');castle.style.zoom=fit;castle.style.width=width+'px';castle.style.height=height+'px';castle.style.setProperty('--content-width',layout.slots*CW()+'px');castle.style.setProperty('--floor-count',floors);if(!castleInitialScroll){castleInitialScroll=true;const scroll=()=>{zone.scrollTop=zone.scrollHeight-zone.clientHeight;zone.scrollLeft=Math.max(0,(zone.scrollWidth-zone.clientWidth)/2);};if(typeof requestAnimationFrame==='function')requestAnimationFrame(scroll);else scroll();}};
  renderHUD=function(){currentHUD();$('#hud .castle-tools')?.remove();const flag=$('#hud .flag');if(flag)flag.textContent=flagEmoji(state.flag);const img=$('#hud .avatar img');if(img&&state.photo.image){img.src=state.photo.image;img.classList.add('personal-avatar');}if(!$('#research-launch'))$('#hud').insertAdjacentHTML('beforeend',button(icon('gear')+'<span>Recherche</span>','open','id="research-launch" data-page="research"','square-button research-launch'));};
  function warEligibility(id){return PreviewGame.warAttackEligibility(state.warAttacks,state.id,id,state.warDay,state.warEnemy);}
  function campaignPoints(){const p=[[.14,.79],[.08,.58],[.16,.41],[.10,.24],[.18,.13],[.20,.33],[.20,.55],[.22,.81]];return Array.from({length:32},(_,i)=>({stage:i+1,x:(Math.floor(i/8)/4+p[i%8][0])*3000,y:p[i%8][1]*1500}));}
  function warPoints(rows,enemy){return rows.map((r,i)=>({...r,x:(enemy?1090:445)+[0,75,-50,60,-35,30,-25,25,-10,0][i],y:1460-i*135,enemy}));}
  function renderFullMap(reset=false){const el=fullMapLayer(),old=$('.full-map-scroll'),sx=old?.scrollLeft||0,sy=old?.scrollTop||0,war=state.mapPage==='war',progress=campaignProgress(),nodes=war?[...warPoints(state.warRoster,false),...warPoints(state.warEnemy,true)]:campaignPoints();el.hidden=false;
    const path=nodes.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' '),icons=nodes.map(p=>{if(!war){const done=progress.cleared.has(p.stage),available=p.stage<=progress.next;return '<button class="journey-castle '+(done?'done':p.stage===progress.next?'current':'locked')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="campaign-stage" data-stage="'+p.stage+'" '+(!available?'disabled':'')+' aria-label="Combat '+p.stage+'">'+art('war:castle:scout')+'<b>'+p.stage+'</b>'+stars(state.campaignStars[p.stage]||0)+'</button>';}
      const done=p.enemy&&warEligibility(p.id).conquered,kind=p.role==='chief'?'chief':p.role==='random'?'scout':'representative';return '<button class="journey-castle war-castle '+p.role+(done?' done':'')+(p.enemy?' enemy':' ally')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="war-node" data-id="'+p.id+'" data-side="'+(p.enemy?'enemy':'ally')+'">'+art('war:castle:'+kind+(done?':ruined':''))+'<strong>'+esc(p.name)+'</strong><small>'+currentRoles[p.role]+' · '+p.points+' pts</small>'+(done?'<b>✓</b>':'')+'</button>';}).join('');
    el.innerHTML='<div class="full-map-scroll"><div class="full-map-world '+(war?'war-world':'campaign-world')+'">'+art(war?'war:map':'campaign:unified','full-map-art')+(war?'':'<svg class="campaign-trail" viewBox="0 0 3000 1500" aria-hidden="true"><path d="'+path+'"/></svg>')+icons+'</div></div><header class="full-map-header">'+button('‹','map-return','aria-label="Retour"','square-button map-return')+'<div><h1>'+(war?'Guerre des clans':'Campagne d’Astral')+'</h1><span>'+(war?esc(state.clan)+' ◀ ▶ '+esc(state.warOpponent)+' · '+(state.demoWarOpen?'Session de test':'8 h – 22 h · Paris'):state.campaignCleared.length+' / 32 châteaux · Terre → Bois → Braise → Givre')+'</span></div><div class="map-summary">'+(war?'<b>'+state.warAttacks.filter(a=>a.playerId===state.id&&(a.day||PreviewGame.v06ParisDay(a.at))===state.warDay&&a.status==='won').length+' / 10 conquis</b><small>'+warEligibility('_').remaining+' défaites restantes</small>':'<b>✦ '+Object.values(state.campaignStars).reduce((n,v)=>n+v,0)+' étoiles</b>')+'</div></header><div class="full-map-footer">'+(war?button('Tournoi et récompenses','open','data-page="war-rewards"','secondary'):button('Combat suivant','campaign-stage','data-stage="'+Math.min(32,progress.next)+'"'))+'<span>Glisse la carte avec un doigt</span></div>';
    const scroller=$('.full-map-scroll');if(reset){if(war)scroller.scrollTop=1500;else{const p=nodes[Math.min(31,progress.next-1)];scroller.scrollLeft=Math.max(0,p.x-650);scroller.scrollTop=Math.max(0,p.y-350);}}else{scroller.scrollLeft=sx;scroller.scrollTop=sy;}}
  function warNodePanel(){const enemy=state.warNodeSide==='enemy',m=(enemy?state.warEnemy:state.warRoster).find(m=>m.id===state.warNodeId);if(!m)return '';const q=warEligibility(m.id),attacks=state.warAttacks.filter(a=>a.targetId===m.id&&(a.day||PreviewGame.v06ParisDay(a.at))===state.warDay),kind=m.role==='chief'?'chief':m.role==='random'?'scout':'representative';return '<div class="detail-layout">'+art('war:castle:'+kind+(enemy&&q.conquered?':ruined':enemy?':enemy':''),'detail-art')+'<div class="detail-copy"><h2>'+esc(m.name)+'</h2><p>'+currentRoles[m.role]+' · Trône '+m.mainLevel+'</p>'+stats([[m.points,'Points de conquête'],[attacks.length,'Attaques reçues'],[attacks.filter(a=>a.status!=='won').length,'Défenses gagnées'],[attacks.filter(a=>a.status==='won').length,'Défenses perdues']])+(enemy?(q.reason?'<p class="prerequisite-warning">'+esc(q.reason)+'</p>':'')+button(q.conquered?'✓ Conquis':'Attaquer','war-attack','data-id="'+m.id+'" '+(!q.allowed||!state.demoWarOpen&&!PreviewGame.v06WarIsOpen()?'disabled':'')):'<p>Sentinelle allié de la guerre actuelle.</p>')+'</div></div>';}
