if(PLAYER_PREVIEW.scenario==='established-player'){const m=homeLayout.buildings.find(o=>o.type==='mana');state.recovery.mana={amount:PreviewGame.manaCapacity(m?.level||0),capacity:PreviewGame.manaCapacity(m?.level||0),lastAt:Date.now()};for(const p of PreviewGame.RECOVERY_ITEMS)state.inventory[p.id]=(state.inventory[p.id]||0)+3;}
state.metrics={...Object.fromEntries(['harvestGold','harvestElixir','harvestGoldCount','harvestElixirCount','lootedGold','lootedElixir','recruited','campaignBattles','campaignWins','campaignStars','pvpBattles','pvpWins','pvpStars','defenseWins','warBattles','wins','stars','construction','buildingsBuilt','xpPotion','donations','helps','heroLevels','heroSkills','heroHeals','wars','researches','destroyed','distinctPvpOpponents'].map(k=>[k,0])),...(state.metrics||{})};
state.challenge330??={daily:{period:dailyKey(),claimed:[],baseline:{}},weekly:{period:challengeWeekKey330(),claimed:[],baseline:{}},permanent:[]};
state.challengeOpponents330??=[];
const challengeStoreKey330='blabox-challenges-028';try{const saved=JSON.parse(window.localStorage?.getItem(challengeStoreKey330)||'null');if(saved?.version===1){state.metrics={...state.metrics,...saved.metrics};state.challenge330=saved.challenge330||state.challenge330;state.challengeOpponents330=saved.opponents||[];}}catch{}
state.progressClaims=[];state.dailyProgress={day:dailyKey(),baseline:{...state.metrics}};state.notificationsLog=[];state.mineHelps=[];state.visitReceipts=[];state.returnCampaign=null;
const progressAction=action,progressModal=renderModal,progressHUD=renderHUD,progressCastle=renderCastle,progressBattleHUD=renderBattleHUD,progressBattleFrame=renderBattleFrame,progressBattleTick=battleTick,progressProducts=products,progressSettings=settings;
const saveFieldsBeforeChallenge330=guideSaveFields;guideSaveFields=function(){return {...saveFieldsBeforeChallenge330(),challenge330:structuredClone(state.challenge330)};};
function notifyGame(id,title,asset='item:gift'){if(state.notificationsLog.some(n=>n.id===id))return;state.notificationsLog.unshift({id,title,asset,at:Date.now()});state.notificationsLog=state.notificationsLog.slice(0,80);}
function recoverNow(){const h=Object.fromEntries(homeLayout.garrisons.map(g=>[g.hero,houseFor(g.hero)?.level||0])),building=homeLayout.buildings.find(b=>b.type==='mana');state.recovery.mana.capacity=PreviewGame.manaCapacity(building?.level||0);state.recovery.mana.enabled=!building?.underConstruction;for(const id of state.ownedHeroes)state.recovery.heroes[id]??={ratio:1,lastAt:Date.now()};state.recovery=PreviewGame.settleRecovery(state.recovery,{mainLevel:state.level,houses:h,active:state.battle?.engine?.status==='running'});}
function liveProgress(){return {...state.metrics,mainLevel:state.level,floors:homeLayout.floors,campaignCleared:state.campaignCleared.length,campaignStars:Object.values(state.campaignStars).reduce((n,v)=>n+v,0),heroes:state.ownedHeroes.size,builders:state.recruitedBuilders,mines:homeLayout.buildings.filter(b=>b.type==='mine'&&!b.underConstruction).length,academies:homeLayout.buildings.filter(b=>b.type==='academie'&&!b.underConstruction).length,manaBuildings:homeLayout.buildings.filter(b=>b.type==='mana'&&!b.underConstruction).length,guards:(homeLayout.monsterGarrisons||[]).length,hasClan:Number(Boolean(state.clan)),houses:homeLayout.buildings.filter(b=>b.type==='caserne-heros').length};}
function challengeWeekKey330(){const d=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d),p=Object.fromEntries(parts.map(x=>[x.type,x.value])),local=new Date(Date.UTC(+p.year,+p.month-1,+p.day)),day=(local.getUTCDay()+6)%7;local.setUTCDate(local.getUTCDate()-day);return local.toISOString().slice(0,10);}
function challengePeriod330(kind){return kind==='daily'?dailyKey():kind==='weekly'?challengeWeekKey330():'permanent';}
function challengeSnapshot330(){return {...liveProgress(),totalHeroLevels:Object.values(state.heroLevels).reduce((n,x)=>n+(Number(x)||0),0),buildingLevel:Math.max(0,...homeLayout.buildings.filter(b=>!b.underConstruction).map(b=>b.level||1))};}
function refreshChallenge330(){state.challenge330??={daily:{period:dailyKey(),claimed:[],baseline:{}},weekly:{period:challengeWeekKey330(),claimed:[],baseline:{}},permanent:[]};for(const kind of ['daily','weekly']){const period=challengePeriod330(kind);if(state.challenge330[kind]?.period!==period)state.challenge330[kind]={period,claimed:[],baseline:challengeSnapshot330()};else state.challenge330[kind].baseline??=challengeSnapshot330();}}
function challengeValue330(p){const current=challengeSnapshot330()[p.metric]||0;if(['daily','weekly'].includes(p.kind)&&!['buildingLevel','totalHeroLevels'].includes(p.metric))return Math.max(0,current-(state.challenge330[p.kind].baseline?.[p.metric]||0));return current;}
const challengePotionMap330={XP150:'xp-small',XP500:'xp-medium','Soin25%':'health-25','Mana+5':'mana-5'};
const challengeSpeedMap330={'5 min':'speed-300','15 min':'speed-900','1 h':'speed-3600','1 jour':'speed-86400'};
function challengeRows330(){refreshChallenge330();const kind=state.tab==='weekly'?'weekly':state.tab==='permanent'?'permanent':'daily';return MODELS.CHALLENGES_330.challenges.filter(p=>p.kind===kind).map(p=>({...p,key:'challenge330:'+kind+':'+challengePeriod330(kind)+':'+p.id,value:challengeValue330(p),claimed:kind==='permanent'?state.challenge330.permanent.includes(p.id):state.challenge330[kind].claimed.includes(p.id)}));}
function challengeReward330(reward){if(reward.diamonds)state.wallet.diamonds+=reward.diamonds;for(const [id,n]of Object.entries(reward.potions||{})){if(id==='XP150')PreviewGame.grantFreeXP0307(state,{small:n});else if(id==='XP500')PreviewGame.grantFreeXP0307(state,{medium:n});else if(id==='Soin25%')state.inventory['health-25']=(state.inventory['health-25']||0)+n;else if(id==='Mana+5')state.inventory['mana-5']=(state.inventory['mana-5']||0)+n;}for(const [label,n]of Object.entries(reward.speedups||{})){const id=challengeSpeedMap330[label];if(id)state.inventory[id]=(state.inventory[id]||0)+n;} }
function updateDaily(){if(state.dailyProgress.day!==dailyKey())state.dailyProgress={day:dailyKey(),baseline:{...state.metrics}};}
function progressRows(){updateDaily();const values=liveProgress();if(state.tab==='achievements')return PreviewGame.ACHIEVEMENTS.map(p=>({...p,key:'achievement:'+p.id,value:values[p.metric]||0,reward:{diamonds:p.diamonds,vials:{small:1}}}));if(state.tab==='journey')return PreviewGame.HERO_JOURNEY.map(p=>({...p,key:'journey:'+p.id,value:values[p.metric]||0,reward:{diamonds:5,vials:{small:1}}}));return PreviewGame.DAILY_QUESTS.filter(p=>p.unlock<=state.level&&(p.id!=='don'||state.clan)).map(p=>({...p,key:'daily:'+state.dailyProgress.day+':'+p.id,value:Math.max(0,(values[p.metric]||0)-(state.dailyProgress.baseline[p.metric]||0)),reward:{diamonds:2,vials:{small:1}}}));}
missions=function(){if(['daily','weekly','permanent'].includes(state.tab)){const rows=challengeRows330(),title={daily:'Défis quotidiens · 10 · réinitialisation à minuit (Paris)',weekly:'Défis hebdomadaires · 20 · lundi à minuit (Paris)',permanent:'Défis permanents · 300'}[state.tab];return '<div class="panel-mini-heading"><b>'+title+'</b></div><div class="challenge330-list">'+rows.map(p=>{const done=p.value>=p.target,reward=[p.reward.diamonds?quantityIcon('diamonds',p.reward.diamonds):'',...Object.entries(p.reward.potions||{}).map(([id,n])=>quantityIcon(challengePotionMap330[id]||id,id.startsWith('XP')?n/4:n)),...Object.entries(p.reward.speedups||{}).map(([id,n])=>quantityIcon(challengeSpeedMap330[id]||id,n))].join('');return '<article class="paper-card mission-row"><div><h3>'+esc(p.name)+'</h3><div class="progress-bar"><i style="width:'+Math.min(100,p.value/p.target*100)+'%"></i></div><b>'+fmt(Math.min(p.value,p.target))+' / '+fmt(p.target)+'</b></div><div class="mission-reward">'+reward+'</div>'+button(p.claimed?'Récupéré':done?'Récupérer':'En cours','challenge330-claim','data-id="'+p.id+'" '+(!done||p.claimed?'disabled':''))+'</article>';}).join('')+'</div>';}return '<div class="panel-mini-heading"><b>'+({achievements:'Accomplissements · 50',journey:'Le parcours du héros'})[state.tab||'achievements']+'</b></div><div class="mission-list">'+progressRows().map(p=>{const claimed=state.progressClaims.includes(p.key),done=p.value>=p.target;return '<article class="paper-card mission-row">'+icon('star','mission-icon')+'<div><h3>'+p.name+'</h3><div class="progress-bar"><i style="width:'+Math.min(100,p.value/p.target*100)+'%"></i></div><b>'+Math.min(p.value,p.target)+' / '+p.target+'</b></div><div class="mission-reward">'+quantityIcon('diamonds',p.reward.diamonds)+quantityIcon('xp-small',.25)+'</div>'+button(claimed?'Récupéré':done?'Récupérer':'En cours','progress-claim','data-key="'+esc(p.key)+'" '+(!done||claimed?'disabled':''))+'</article>';}).join('')+'</div>';};
products=function(){if(state.category==='potions')return PreviewGame.RECOVERY_ITEMS.map(p=>({...p,currency:'diamonds',item:p.id,description:p.mana?'Recharge hors combat':'Soin hors combat'}));return progressProducts().map(p=>p.hero?{...p,description:heroes.find(h=>h.id===p.hero)?.role||p.description}:p);};
shopCategories.push(['potions','Potions','xp-medium']);
inventory=function(){const rows=[...Object.entries(state.vials).map(([id,n])=>({id:'xp-'+id,n,name:'Potion XP · '+({small:'petite',medium:'moyenne',large:'grande'})[id],asset:'item:xp-'+id,a:'inventory-vial'})),...Object.entries(state.inventory).map(([id,n])=>{const p=PreviewGame.RECOVERY_ITEMS.find(p=>p.id===id),speed=Number(id.replace('speed-',''));return {id,n,name:p?.name|| (id.startsWith('shield-')?'Bouclier · '+({'shield-1d':'1 jour','shield-7d':'7 jours','shield-30d':'30 jours'}[id]):id==='energy-refill'?'Recharge d’énergie':id==='clan-banner'?'Bannière du clan':id.startsWith('speed-')?'Accélérateur · '+exactTime(speed):'Objet du royaume'),asset:p?.asset||'item:'+id,a:'use-item'};})];return '<div class="inventory-grid">'+rows.map(p=>'<article class="paper-card unit-card">'+art(p.asset)+'<strong>'+p.name+'</strong><span class="quantity">× '+p.n+'</span>'+button(p.id.startsWith('xp-')?'Choisir un héros':'Utiliser',p.a,'data-id="'+p.id+'" '+(!p.n?'disabled':''))+'</article>').join('')+Object.entries(state.pendingResources||{}).filter(([,n])=>n>0).map(([id,n])=>'<article class="paper-card unit-card">'+icon(id)+'<strong>Ressources reçues</strong><span class="quantity">'+fmt(n)+'</span>'+button('Récupérer','resource-claim','data-id="'+id+'"')+'</article>').join('')+'</div>';};
function itemUsePanel(){const p=PreviewGame.RECOVERY_ITEMS.find(p=>p.id===state.itemToUse);if(p?.heal)return '<div class="panel-mini-heading"><b>Choisis le héros à soigner</b>'+art(p.asset)+'</div><div class="card-grid">'+heroes.filter(h=>state.ownedHeroes.has(h.id)).map(h=>{const ratio=state.recovery.heroes[h.id]?.ratio??1;return '<article class="paper-card unit-card">'+heroArt(h.id)+'<strong>'+h.name+'</strong><b>'+Math.round(ratio*100)+' % de vie</b>'+button('Soigner','recovery-use','data-id="'+p.id+'" data-hero="'+h.id+'" '+(ratio>=1?'disabled':''))+'</article>';}).join('')+'</div>';const seconds=Number(state.itemToUse.replace('speed-',''));return '<div class="panel-mini-heading"><b>Accélérer de '+exactTime(seconds)+'</b>'+icon('speed-3600')+'</div><div class="mission-list">'+state.jobs.map(j=>'<article class="paper-card mission-row"><h3>'+esc(j.name)+'</h3><b>'+exactTime((j.endsAt-Date.now())/1000)+'</b>'+button('Utiliser','speed-item-apply','data-id="'+j.id+'"')+'</article>').join('')+(state.research?'<article class="paper-card mission-row"><h3>Recherche de monstres</h3><b>'+exactTime((state.research.endsAt-Date.now())/1000)+'</b>'+button('Utiliser','speed-item-apply','data-id="research"')+'</article>':'')+'</div>'+(!state.jobs.length&&!state.research?'<p>Aucun chantier ni recherche en cours.</p>':'');}
const mineCapacityBefore=mineCapacity;mineCapacity=function(o){return Math.round(mineCapacityBefore(o)*(o.helpUntil>Date.now()?1.2:1));};
const minesBefore=settleMines;settleMines=function(now=Date.now()){const previous=new Map(homeLayout.buildings.map(o=>[o.id,{stored:o.stored||0,at:o.producedAt||now}]));minesBefore(now);for(const o of homeLayout.buildings.filter(o=>['mine','extracteur'].includes(o.type))){if(o.helpUntil>now&&!o.underConstruction){const p=previous.get(o.id);o.stored=Math.min(mineCapacity(o),o.stored+.2*Math.max(0,o.stored-p.stored));}}};
const recruitmentBefore=recruitmentState;recruitmentState=function(){return {...recruitmentBefore(),reservedCount:0};};
const recruitmentAcceptBefore=acceptRecruitment;acceptRecruitment=function(s){if(s.delivered?.length){state.metrics.recruited+=s.delivered.length;for(const d of s.delivered)rewardFloat('monster:'+d.troop+':n'+String(state.monsterLevels[d.troop]).padStart(2,'0'),'+1');if(!s.recruitment.length)notifyGame('army:'+Date.now(),'Ton armée est prête','item:attack');}recruitmentAcceptBefore(s);};
const attackerBefore=demoAttacker;demoAttacker=function(weak=false){recoverNow();const s=attackerBefore(weak);s.army.heroes=s.army.heroes.filter(id=>PreviewGame.heroReady(state.recovery,id));return s;};
const beginBefore=beginBattle;beginBattle=function(mode,index){recoverNow();if(!state.troops&&!state.formation.some(id=>PreviewGame.heroReady(state.recovery,id))){toast('Tes héros récupèrent. Prépare des troupes ou utilise une potion de soin.');return;}beginBefore(mode,index);const b=state.battle;if(!b||b.replay)return;b.engine.id=currentId('battle');b.engine.useMana=true;b.engine.mana={amount:state.recovery.mana.enabled?state.recovery.mana.amount:0,capacity:state.recovery.mana.capacity};for(const u of b.engine.units.filter(u=>u.hero))u.hp=u.maxHp*(state.recovery.heroes[u.hero]?.ratio??1);renderBattleHUD();};
function manaMarkup(battle=false){const m=battle?(state.battle?.replay?state.battle.history.frames[state.battle.cursor]?.mana:state.battle?.engine?.mana):state.recovery.mana;if(!m?.capacity)return '';return button(icon('mana-5')+'<span><b>'+Math.floor(m.amount)+' / '+m.capacity+'</b><small>Mana</small></span>',battle?'cast-dismiss':'mana-open','','mana-panel');}
renderHUD=function(){recoverNow();progressHUD();$('#hud').insertAdjacentHTML('beforeend',manaMarkup());};
renderCastle=function(){progressCastle();for(const g of homeLayout.garrisons){const el=$('.building[data-id="'+g.id+'"]'),ratio=state.recovery.heroes[g.hero]?.ratio??1;el?.classList.toggle('out-hero',ratio<=.15);if(el&&ratio<=.15)el.insertAdjacentHTML('beforeend','<span class="hero-out-tag">Out · '+Math.round(ratio*100)+' %</span>');}if(!state.battle)for(const g of homeLayout.monsterGarrisons||[]){const h=homeLayout.buildings.find(h=>h.id===g.houseId);if(!h)continue;g.floor=h.floor;g.x=h.x;const f=$('.castle-floor[data-floor="'+h.floor+'"]');f?.insertAdjacentHTML('beforeend','<span class="guard-patrol" style="left:'+(h.x+.3)*CW()+'px">'+profileMarkup('monster',g.troop,'walk',1,0)+'</span>');}};
function castPanel(){const b=state.battle;if(!b||b.replay||!state.castHero)return '';const u=b.engine.units.find(u=>u.hero===state.castHero&&!u.summoned);if(!u)return '';const q=PreviewGame.spellAvailability(b.engine,u),h=heroes.find(h=>h.id===u.hero);if(!PreviewGame.SPELL_RULES[u.hero])return '<div class="hero-cast-panel">'+heroArt(u.hero)+'<b>'+h.name+'</b><span>Compétences passives</span>'+button('×','cast-dismiss','','secondary')+'</div>';return '<div class="hero-cast-panel">'+heroArt(u.hero)+'<div><b>'+h.name+'</b><small>'+fmt(Math.floor(b.engine.mana.amount))+' mana</small></div>'+button(spellArt(u.hero,1)+'<span>'+spellNames[u.hero][0]+'</span><span class="spell-uses">'+('× '+q.remaining+(q.cooldown?' · '+exactTime(q.cooldown):''))+' · '+(q.cost||0)+' mana</span>','spell','data-id="'+u.hero+'-1" '+(!q.allowed?'disabled':'')+' title="'+esc(q.reason||'Utiliser la compétence')+'"','primary')+button('×','cast-dismiss','','secondary')+'</div>';}
// Conserver les commandes de sort pendant les images du combat : seuls leurs états changent.
function refreshCastPanel(){
 const b=state.battle,u=b&&!b.replay&&state.castHero?b.engine.units.find(u=>u.hero===state.castHero&&!u.summoned):null;
 let panel=$('.hero-cast-panel');if(!u){panel?.remove();return;}
 if(!panel||panel.dataset.castHero!==u.hero){panel?.remove();$('#battle-hud').insertAdjacentHTML('beforeend',castPanel());panel=$('.hero-cast-panel');if(panel)panel.dataset.castHero=u.hero;}
 if(!panel||!PreviewGame.SPELL_RULES[u.hero])return;
 const q=PreviewGame.spellAvailability(b.engine,u),command=panel.querySelector('[data-action="spell"]'),mana=panel.querySelector('div small');
 const manaText=fmt(Math.floor(b.engine.mana.amount))+' mana';if(mana&&mana.textContent!==manaText)mana.textContent=manaText;
 if(command){command.disabled=!q.allowed;command.title=q.reason||'Utiliser la compétence';const uses=command.querySelector('.spell-uses'),text='× '+q.remaining+(q.cooldown?' · '+exactTime(q.cooldown):'')+' · '+(q.cost||0)+' mana';if(uses&&uses.textContent!==text)uses.textContent=text;}
}
function paintBattleSummary(f){const raw=f.destruction?.raw||0,n=f.destruction?.stars||0,label=$('#battle-floor');if(label)label.textContent=raw.toLocaleString('fr-FR',{maximumFractionDigits:1})+' %';const fill=$('#battle-percent');if(fill)fill.style.width=raw+'%';const root=$('.battle-progress');if(root){root.querySelector('.battle-stars')?.remove();root.querySelector('.battle-victory')?.remove();root.insertAdjacentHTML('beforeend','<div class="battle-stars">'+Array.from({length:4},(_,i)=>icon(i<n?'star':'star-empty',i<n?'lit':'')).join('')+'</div><div class="battle-victory">'+(f.victorySecured?'Victoire acquise':n?'':'')+'</div>');}const mana=$('#battle-hud .mana-panel');if(mana)mana.outerHTML=manaMarkup(true);}
renderBattleHUD=function(){progressBattleHUD();$('#battle-hud').insertAdjacentHTML('beforeend',manaMarkup(true));refreshCastPanel();paintBattleSummary(state.battle.engine||state.battle.history.frames[state.battle.cursor]);};
renderBattleFrame=function(f){progressBattleFrame(f);paintBattleSummary(f);refreshCastPanel();for(const u of f.units.filter(u=>u.hero&&u.hp>0)){const el=$('.war-walker[data-unit="'+u.id+'"]');if(el)el.insertAdjacentHTML('beforeend',button('','cast-hero','data-id="'+u.hero+'" aria-label="Compétences de '+esc(u.name||u.hero)+'"','hero-spell-trigger'));}for(const d of f.structures.filter(d=>d.guard&&d.troop&&d.hp>0)){const el=$('.castle-floor[data-floor="'+d.floor+'"]');el?.insertAdjacentHTML('beforeend','<span class="war-walker guard-patrol" style="left:'+d.x*CW()+'px">'+profileMarkup('monster',d.troop,d.animState,d.direction)+'</span>');}for(const d of f.structures.filter(d=>d.hero)){const el=$('.building[data-id="'+d.id+'"]');el?.classList.toggle('rage-hero',d.rageUntil>f.time);}if(Date.now()-lastCameraInput>3500&&state.cameraFloor!==f.floor){state.cameraFloor=f.floor;const el=$('.castle-floor[data-floor="'+f.floor+'"]'),r=el?.getBoundingClientRect?.(),stage=$('#stage').getBoundingClientRect?.();if(r&&stage){state.camera.y+=((stage.top+stage.height*.47)-(r.top+r.height/2))/(innerWidth/1600);applyCamera();}}for(const ev of f.events||[])if(ev.type==='shot')testSound('hit');else if(ev.type==='dead')testSound('break');};
battleTick=function(){progressBattleTick();const b=state.battle;if(b&&!b.replay&&b.engine.status!=='running'&&!state.recovery.processed.includes(b.engine.id)&&b.mode!=='self-test'){const necro=Math.max(0,...homeLayout.defenses.filter(d=>d.type==='necropole'&&!d.underConstruction).map(d=>d.level)),won=b.engine.status==='won',stars=b.engine.destruction.stars||0;state.recovery=PreviewGame.recordBattleRecovery(state.recovery,b.engine,{necropolisLevel:necro});state.metrics.wins+=Number(won);state.metrics.stars+=stars;state.metrics.campaignBattles+=Number(b.mode==='campaign');state.metrics.campaignWins+=Number(b.mode==='campaign'&&won);state.metrics.campaignStars+=b.mode==='campaign'?stars:0;state.metrics.pvpBattles+=Number(b.mode==='pvp');state.metrics.pvpWins+=Number(b.mode==='pvp'&&won);state.metrics.pvpStars+=b.mode==='pvp'?stars:0;state.metrics.defenseWins+=Number(b.mode==='defense'&&won);state.metrics.warBattles+=Number(b.mode==='war');state.metrics.wars+=Number(b.mode==='war');if(b.mode==='pvp'&&!state.challengeOpponents330.includes(b.index)){state.challengeOpponents330.push(b.index);state.challengeOpponents330=state.challengeOpponents330.slice(-300);state.metrics.distinctPvpOpponents=state.challengeOpponents330.length;}state.metrics.destroyed+=(b.engine.units||[]).filter(u=>u.hp<=0&&!u.hero).length;const result=b.history?.result||b.result||{};state.metrics.lootedGold=(state.metrics.lootedGold||0)+(result.gold||0);state.metrics.lootedElixir=(state.metrics.lootedElixir||0)+(result.elixir||0);notifyGame(b.engine.id,'Combat terminé : '+(won?'victoire':'défaite'),'item:attack');renderHUD();saveCurrentProgress();}};
const heroDetailBefore=heroDetail;heroDetail=function(){const id=state.heroId,q=PreviewGame.SPELL_RULES[id];let slot=0;const s=heroDetailBefore().replace(/<small>Une seule utilisation par combat<\/small>/g,()=>{slot++;return '<small>'+(slot===1&&q?q.cost+' mana · '+q.limit+' utilisation'+(q.limit>1?'s':'')+(q.cooldown?' · '+q.cooldown+' s':''):'Compétence passive')+'</small>';});if(!state.ownedHeroes.has(id))return s;recoverNow();const ratio=state.recovery.heroes[id]?.ratio??1,remaining=PreviewGame.recoveryRemaining(state.recovery,id,state.level,houseFor(id)?.level||0);return s+'<section class="hero-health-detail"><b>'+Math.round(ratio*100)+' % de vie</b><span> · '+(ratio>=1?'Prêt':ratio<=.15?'Out · ':'')+(ratio<1?'Soin complet dans '+exactTime(remaining/1000):'')+'</span><div class="recovery-potions">'+PreviewGame.RECOVERY_ITEMS.filter(p=>p.heal).map(p=>button(art(p.asset)+'+'+Math.round(p.heal*100)+' % · '+(state.inventory[p.id]||0),'recovery-use','data-id="'+p.id+'" data-hero="'+id+'" '+(!state.inventory[p.id]||ratio>=1?'disabled':''),'secondary')).join('')+'</div></section>';};
const housingPanelBefore=housingPanel;housingPanel=function(o){const s=housingPanelBefore(o);if(homeLayout.garrisons.some(g=>g.hero==='tiko'&&g.caserneId===o.id)&&!syncBuilderSlots().canRemoveTiko)return s.replace('data-action="housing-clear"','disabled title="Tous les constructeurs sont occupés" data-action="housing-clear"');return s;};
function manaPanel(){recoverNow();const m=state.recovery.mana,seconds=(m.capacity-m.amount)/PreviewGame.MANA_RULES.perSecond;return '<div class="detail-layout">'+art('building:mana','detail-art')+'<div class="detail-copy"><h2>Le mana de tes héros</h2>'+stats([[Math.floor(m.amount)+' / '+m.capacity,'Mana'],[m.amount>=m.capacity?'Complet':exactTime(seconds),'Récupération']])+'<p>Se recharge au château. Aucune recharge en combat.</p><div class="recovery-potions">'+PreviewGame.RECOVERY_ITEMS.filter(p=>p.mana).map(p=>button(art(p.asset)+'+'+p.mana+' · '+(state.inventory[p.id]||0),'recovery-use','data-id="'+p.id+'" '+(!state.inventory[p.id]||m.amount>=m.capacity?'disabled':''),'secondary')).join('')+'</div></div></div>';}
function guardPanel(house){const gs=(homeLayout.monsterGarrisons||[]).filter(g=>g.houseId===house.id),cap=PreviewGame.guardCapacity(house.level);return '<section class="housing-panel"><h3>Garnison de monstres · '+gs.length+' / '+cap+'</h3><div class="guard-choice">'+gs.map(g=>button(monsterArt(g.troop,g.level)+'Retirer','guard-clear','data-id="'+g.id+'"','secondary')).join('')+state.roster.filter(r=>r.count>0).map(r=>button(monsterArt(r.troop,state.monsterLevels[r.troop])+MODELS.TROOPS.find(t=>t.id===r.troop).name+' · ×'+r.count,'guard-assign','data-house="'+house.id+'" data-id="'+r.troop+'" '+(gs.length>=cap||house.underConstruction?'disabled':''),'primary')).join('')+'</div><p>Une place au niveau 3, deux au niveau 5, quatre au niveau 10.</p></section>';}
function notificationPanel(){return state.notificationsLog.map(n=>'<article class="notification-row">'+art(n.asset)+'<div><b>'+esc(n.title)+'</b><small>'+new Date(n.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})+'</small></div></article>').join('')||'<p>Aucune nouvelle notification.</p>';}
function returnPanel(){const c=state.returnCampaign;if(!c)return '<p>Le programme de retour apparaîtra lorsqu’il sera disponible.</p>';return '<div class="panel-mini-heading"><b>Bon retour au château</b><span>'+c.days.length+' / 7 cadeaux</span></div><div class="return-calendar">'+PreviewGame.RETURN_REWARDS.map((r,i)=>'<article class="paper-card">'+icon(i===6?'diamond-chest':'gift')+'<h3>Jour '+(i+1)+'</h3>'+(i===6&&c.hero?'<div class="return-hero">'+heroArt(c.hero)+'<b>'+heroes.find(h=>h.id===c.hero)?.name+'</b></div>':'')+'<div>'+(r.diamonds?quantityIcon('diamonds',r.diamonds):'')+Object.entries(r.resourceFractions||{}).map(([k,f])=>quantityIcon(k,Math.floor(capFor(k)*f))).join('')+Object.entries(r.items||{}).map(([k,n])=>quantityIcon(k,n)).join('')+Object.entries(r.vials||{}).map(([k,n])=>quantityIcon('xp-'+k,n)).join('')+'</div>'+button(i<c.days.length?'Récupéré':'Récupérer','return-claim',i!==c.days.length||c.days.includes(dailyKey())?'disabled':'')+'</article>').join('')+'</div>';}
const visitedCastles=new Map();
function visitPanel(){const owner=state.visitedCastle;if(!owner)return '';return '<div class="panel-mini-heading"><b>'+esc(owner.name)+'</b><span>'+state.mineHelps.filter(h=>h.day===dailyKey()).length+' / 6 aides</span></div><div class="card-grid">'+owner.layout.buildings.filter(o=>['mine','extracteur'].includes(o.type)).map(o=>'<article class="paper-card unit-card visited-mine">'+art('building:'+o.type)+'<h3>'+meta(o).name+'</h3><b>Niveau '+o.level+'</b>'+button(o.helpDay===dailyKey()?'Aidée aujourd’hui':'Aider','mine-help','data-id="'+o.id+'" '+(o.helpDay===dailyKey()?'disabled':''))+'</article>').join('')+'</div>';}
settings=function(){return progressSettings()+'<div class="detail-actions">'+button('Notifications','open','data-page="notifications"','secondary')+button('Musique et effets','open','data-page="audio"','secondary')+button('Tester un retour après absence','return-demo','','secondary')+'</div><label class="settings-code">Code cadeau<input id="settings-reward-code" maxlength="40" placeholder="Ton code"></label>'+button('Valider le code','settings-code-redeem');};
renderModal=function(){const custom=state.modal==='mana'?manaPanel():state.modal==='notifications'?notificationPanel():state.modal==='return'?returnPanel():state.modal==='visit-castle'?visitPanel():state.modal==='audio'?audioPanel():state.modal==='item-use'?itemUsePanel():null;if(custom!==null){$('#modal-title').textContent=({mana:'Mana',notifications:'Notifications',return:'Bon retour', 'visit-castle':state.visitedCastle?.name||'Visite',audio:'Ambiance du royaume','item-use':'Utiliser un objet'})[state.modal];$('#modal-body').innerHTML=custom;$('#modal-tabs').innerHTML='';$('#modal').classList.remove('shop-modal');enhanceSelects();}else progressModal();if(state.modal==='info'){const o=object(state.infoId);if(o?.type==='academie')$('#modal-body').insertAdjacentHTML('beforeend',button('Recherches des monstres','open','data-page="research"'));if(o?.type==='mana')$('#modal-body').insertAdjacentHTML('beforeend',button('Voir le mana','mana-open'));if(o?.type==='garde-monstres')$('#modal-body').insertAdjacentHTML('beforeend',guardPanel(o));}if(state.modal==='army'&&state.tab==='heroes')for(const id of state.ownedHeroes){const card=$('#modal-body [data-action="hero"][data-id="'+id+'"]')?.closest('.unit-card');if(card&&!PreviewGame.heroReady(state.recovery,id))card.insertAdjacentHTML('beforeend','<b class="hero-out-tag">Out</b>');}};
function saveChallengeProgress330(){try{window.localStorage?.setItem(challengeStoreKey330,JSON.stringify({version:1,metrics:state.metrics,challenge330:state.challenge330,opponents:state.challengeOpponents330}));}catch{}}
function saveCurrentProgress(){saveChallengeProgress330();if(state.journey?.version===2){saveJourney();return;}persistPreviewGame(PLAYER_PREVIEW.storageKey,{format:'preview-only',state:guideSaveFields(),layout:homeLayout,ownedHeroes:[...state.ownedHeroes],battle:previewBattleSnapshot()});}

action=function(a,d={},node){try{
if(a==='use-item'&&PreviewGame.RECOVERY_ITEMS.some(p=>p.id===d.id)){const p=PreviewGame.RECOVERY_ITEMS.find(p=>p.id===d.id);if(p.mana){action('recovery-use',d,node);return;}state.itemToUse=d.id;open('item-use');return;}
if(a==='use-item'&&d.id.startsWith('speed-')){if(!state.inventory[d.id])throw Error('Accélérateur indisponible.');state.itemToUse=d.id;open('item-use');return;}
if(a==='use-item'&&d.id==='clan-banner'){open('clan','members');return;}
if(a==='speed-item-apply'){if(state.battle?.engine?.status==='running')throw Error('Utilise les accélérateurs au château.');const id=state.itemToUse,seconds=Number(id.replace('speed-','')),j=d.id==='research'?state.research:state.jobs.find(j=>j.id===d.id);if(!j||!state.inventory[id]||!seconds)throw Error('Ce chantier n’est plus disponible.');state.inventory[id]--;j.endsAt-=seconds*1000;completeJobs();renderCastle();renderHUD();renderModal();rewardFloat('item:speed-3600','Accéléré');saveCurrentProgress();return;}
if(a==='resource-claim'){const available=state.pendingResources?.[d.id]||0,n=Math.min(available,Math.max(0,capFor(d.id)-state.wallet[d.id]));if(!n)throw Error('Ta réserve est pleine.');state.pendingResources[d.id]-=n;state.wallet[d.id]+=n;renderHUD();renderModal();rewardFloat('item:'+d.id,'+'+fmt(n));saveCurrentProgress();return;}
if(a==='audio-voice'){if(!personalVoice)throw Error('Importe une voix pour la tester.');personalVoice.volume=state.audioVolumes.voices;personalVoice.currentTime=0;personalVoice.play().catch(()=>toast('Ce format audio n’est pas disponible.'));return;}
if(a==='challenge330-claim'){refreshChallenge330();const p=challengeRows330().find(p=>p.id===d.id);if(!p||p.value<p.target||p.claimed)throw Error('Défi indisponible.');challengeReward330(p.reward);if(p.kind==='permanent')state.challenge330.permanent.push(p.id);else state.challenge330[p.kind].claimed.push(p.id);renderHUD();renderModal();rewardFloat('item:gift','Récompense obtenue');saveCurrentProgress();return;}
if(a==='progress-claim'){const p=progressRows().find(p=>p.key===d.key);if(!p)throw Error('Objectif inconnu.');const claimInput={xpRewardRemainder0307:state.xpRewardRemainder0307,wallet:state.wallet,vials:state.vials,inventory:state.inventory,claims:state.progressClaims,resourceCaps:{gold:capFor('gold'),elixir:capFor('elixir')}},overflow=PreviewGame.progressRewardOverflow(claimInput,p.reward);if(overflow.length){const lost=overflow.map(x=>fmt(x.amount)+' '+(x.resource==='gold'?'or':'élixir')).join(' et ');if(!confirm('La récompense dépasse la capacité de ta réserve. Veux-tu continuer ?\n'+lost+' seront perdus.'))return;}const r=PreviewGame.claimProgressReward(claimInput,p.key,p.value>=p.target,p.reward,{discardOverflow:true});Object.assign(state,{xpRewardRemainder0307:r.xpRewardRemainder0307,wallet:r.wallet,vials:r.vials,inventory:r.inventory,progressClaims:r.claims});renderHUD();renderModal();rewardFloat('item:gift','Récompense obtenue');saveCurrentProgress();return;}
if(a==='cast-hero'){state.castHero=d.id;renderBattleHUD();return;}
if(a==='cast-dismiss'){state.castHero=null;$('.hero-cast-panel')?.remove();return;}
if(a==='mana-open'){if(state.battle?.engine?.status==='running')throw Error('Aucune recharge pendant le combat.');open('mana');return;}
if(a==='recovery-use'){recoverNow();const r=PreviewGame.useRecoveryItem(state.recovery,state.inventory,d.id,d.hero,{active:state.battle?.engine?.status==='running'});state.recovery=r.recovery;state.inventory=r.inventory;renderHUD();renderCastle();renderModal();rewardFloat('item:'+d.id,'Potion utilisée');saveCurrentProgress();return;}
if(a==='guard-assign'){const r=PreviewGame.assignMonsterGuard(homeLayout,state.roster,d.house,d.id,state.monsterLevels,MODELS.TROOP_UNLOCKS,state.level);Object.assign(homeLayout,r.layout);state.roster=r.roster;state.troops=r.roster.reduce((n,t)=>n+t.count,0);renderCastle();renderHUD();renderModal();saveCurrentProgress();return;}
if(a==='guard-clear'){const g=homeLayout.monsterGarrisons.find(g=>g.id===d.id);if(!g)return;const r=state.roster.find(r=>r.troop===g.troop);if(r)r.count++;else state.roster.push({troop:g.troop,count:1});homeLayout.monsterGarrisons=homeLayout.monsterGarrisons.filter(g=>g.id!==d.id);state.troops++;renderCastle();renderHUD();renderModal();saveCurrentProgress();return;}
if(a==='visit-castle'){const id=d.id||'member-1';if(!visitedCastles.has(id)){const member=state.members.find(m=>m.id===id);visitedCastles.set(id,{id,name:member?.name||state.visited?.name||'Forteresse de Lyra',layout:structuredClone(homeLayout),bot:false});}state.visitedCastle=visitedCastles.get(id);open('visit-castle');return;}
if(a==='mine-help'){const r=PreviewGame.helpMine({id:state.id,wallet:state.wallet,mineHelps:state.mineHelps,visitReceipts:state.visitReceipts},state.visitedCastle,d.id,{commandId:currentId('help')});state.wallet=r.visitor.wallet;state.mineHelps=r.visitor.mineHelps;state.visitReceipts=r.visitor.visitReceipts;state.visitedCastle=r.owner;visitedCastles.set(r.owner.id,r.owner);state.metrics.helps++;renderHUD();renderModal();rewardFloat('item:diamonds','+1',node);saveCurrentProgress();return;}
if(a==='return-demo'){state.returnCampaign={startedAt:Date.now(),days:[],demo:true,hero:PreviewGame.returnEpicHero([...state.ownedHeroes],String(Date.now()))};open('return');return;}
if(a==='return-claim'){const input={xpRewardRemainder0307:state.xpRewardRemainder0307,wallet:state.wallet,vials:state.vials,inventory:state.inventory,claims:state.progressClaims,returnCampaign:state.returnCampaign,resourceCaps:{gold:capFor('gold'),elixir:capFor('elixir')},pendingResources:state.pendingResources||{}},reward=PreviewGame.RETURN_REWARDS[state.returnCampaign?.days?.length||0],overflow=PreviewGame.progressRewardOverflow(input,reward||{});if(overflow.length){const lost=overflow.map(x=>fmt(x.amount)+' '+(x.resource==='gold'?'or':'élixir')).join(' et ');if(!confirm('La récompense dépasse la capacité de ta réserve. Veux-tu continuer ?\n'+lost+' seront perdus.'))return;}const r=PreviewGame.claimReturnReward(input,Date.now(),{discardOverflow:true});Object.assign(state,{xpRewardRemainder0307:r.xpRewardRemainder0307,wallet:r.wallet,vials:r.vials,inventory:r.inventory,progressClaims:r.claims,returnCampaign:r.returnCampaign,pendingResources:r.pendingResources||{}});renderHUD();renderModal();rewardFloat('item:gift','Cadeau obtenu');saveCurrentProgress();return;}
if(a==='settings-code-redeem'){const value=$('#settings-reward-code').value;open('reward-code');$('#reward-code').value=value;progressAction('code-redeem',{},node);return;}
if(a==='audio-test'){testSound(d.kind,true);return;}
if(a==='audio-music'){toggleMusic();renderModal();return;}
const beforeWallet={...state.wallet},beforeJobs=new Set(state.jobs.map(j=>j.id)),beforeHeroes=new Set(state.ownedHeroes),beforeLevels={...state.heroLevels};progressAction(a,d,node);if(a==='collect'&&state.wallet.gold>beforeWallet.gold){state.metrics.harvestGold++;state.metrics.harvestGoldCount++;state.metrics.harvestGoldAmount=(state.metrics.harvestGoldAmount||0)+state.wallet.gold-beforeWallet.gold;}if(a==='collect'&&state.wallet.elixir>beforeWallet.elixir){state.metrics.harvestElixir++;state.metrics.harvestElixirCount++;state.metrics.harvestElixirAmount=(state.metrics.harvestElixirAmount||0)+state.wallet.elixir-beforeWallet.elixir;}if(a==='vial')state.metrics.xpPotion++;if(a==='spell')state.metrics.heroSkills++;if(a==='recovery-use'&&d.hero)state.metrics.heroHeals++;if(a==='clan-donate'||a==='donate')state.metrics.donations++;for(const id of state.ownedHeroes)if(state.heroLevels[id]>beforeLevels[id])state.metrics.heroLevels++;for(const j of state.jobs)if(!beforeJobs.has(j.id)){state.metrics.construction++;state.metrics.buildingsBuilt++;notifyGame('start:'+j.id,j.name+' : chantier lancé','ui:builder');}
if(a==='visit-player'&&state.modal==='player-visit')$('#modal-body').insertAdjacentHTML('beforeend',button('Visiter le château','visit-castle','data-id="visitor-'+d.id+'"'));
if(a==='clan-nominate'&&state.modal==='clan-role')$('#modal-body').insertAdjacentHTML('beforeend',button('Visiter le château','visit-castle','data-id="'+d.id+'"','secondary'));
if(a==='purchase-confirm')for(const id of state.ownedHeroes)if(!beforeHeroes.has(id))state.recovery.heroes[id]={ratio:1,lastAt:Date.now()};
saveCurrentProgress();}catch(e){toast(e.message);}};
// Audio de test autonome. Les pistes personnelles peuvent être importées localement.
state.audioVolumes={music:.12,effects:.12,voices:.5};let audioContext=null,musicTimer=null,personalAudio=null,personalVoice=null,lastSound=0;
function tone(hz,duration=.12,volume=.1,type='sine'){const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)return;audioContext??=new C();audioContext.resume?.();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=audioContext.currentTime;osc.type=type;osc.frequency.setValueAtTime(hz,at);gain.gain.setValueAtTime(volume,at);gain.gain.exponentialRampToValueAtTime(.001,at+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start(at);osc.stop(at+duration);}
function testSound(kind,force=false){if(!state.sound||!force&&Date.now()-lastSound<90)return;lastSound=Date.now();tone(kind==='break'?100:kind==='reward'?880:320,.12,state.audioVolumes.effects,kind==='hit'?'triangle':'sine');}
function toggleMusic(){if(musicTimer||personalAudio&&!personalAudio.paused){clearInterval(musicTimer);musicTimer=null;personalAudio?.pause();return;}if(personalAudio){personalAudio.volume=state.audioVolumes.music;personalAudio.play().catch(()=>toast('Clique de nouveau pour lancer la musique.'));return;}let n=0;const melody=[261.63,329.63,392,523.25,392,329.63,293.66,392];musicTimer=setInterval(()=>tone(melody[n++%melody.length],.65,state.audioVolumes.music),600);}
function audioPanel(){return '<div class="audio-settings">'+[['music','Musique'],['effects','Effets'],['voices','Voix']].map(([id,label])=>'<label>'+label+'<input type="range" min="0" max="100" data-volume="'+id+'" value="'+Math.round(state.audioVolumes[id]*100)+'"></label>').join('')+'</div><div class="center-actions">'+button(musicTimer||personalAudio&&!personalAudio.paused?'Arrêter la musique':'Écouter la musique de test','audio-music')+button('Tester un impact','audio-test','data-kind="hit"','secondary')+button('Tester une récompense','audio-test','data-kind="reward"','secondary')+button('Tester la voix importée','audio-voice',personalVoice?'':'disabled','secondary')+'</div><label>Importer une piste personnelle<input id="personal-audio" type="file" accept="audio/*"></label><label>Importer une voix<input id="personal-voice" type="file" accept="audio/*"></label><p>Ambiance de test synthétique. Ta piste importée reste sur cet appareil.</p>';}
document.addEventListener('input',e=>{if(e.target.dataset.volume){state.audioVolumes[e.target.dataset.volume]=Number(e.target.value)/100;if(personalAudio)personalAudio.volume=state.audioVolumes.music;}if(e.target.id==='personal-voice'&&e.target.files?.[0]){personalVoice=new Audio(URL.createObjectURL(e.target.files[0]));renderModal();}});document.addEventListener('change',e=>{if(e.target.id==='personal-audio'&&e.target.files?.[0]){personalAudio?.pause();personalAudio=new Audio(URL.createObjectURL(e.target.files[0]));personalAudio.loop=true;personalAudio.volume=state.audioVolumes.music;}if(e.target.id==='personal-voice'&&e.target.files?.[0]){personalVoice=new Audio(URL.createObjectURL(e.target.files[0]));renderModal();}});
