function guideStep(step){state.journey.step=step;state.journey.events.push({step,at:Date.now()});saveJourney();renderHUD();}
function guideAfterBuild(){
 if(!guideActive())return;
 const step=state.journey.step;
 if(step==='mine-finish'){
  const mine=homeObject(state.journey.firstMineId);
  if(mine&&!mine.underConstruction){mine.stored=Math.max(mine.stored||0,180);state.selected=mine.id;guideStep('collect');}
 }else if(step==='core-finish'){
  if(state.level>=2&&!homeObject('building:core')?.underConstruction){state.inventory['speed-1800']=(state.inventory['speed-1800']||0)+1;guideStep('house');}
 }else if(step==='barracks-finish'){
  const barracks=homeObject(state.journey.firstBarracksId);
  if(barracks&&!barracks.underConstruction){state.selected=barracks.id;guideStep(state.troops>=10?'buttons':'recruit');}
 }else if(step==='recruit-wait'&&state.troops>=10&&!state.queue){
  close(true);state.selected=null;guideStep('buttons');
 }else if(step==='house-finish'){
  const house=homeObject(state.journey.firstHouseId);
  if(house&&!house.underConstruction){state.selected=house.id;guideStep('garrison');}
 }
}
