function guideTarget(){
 if(!guideActive())return null;
 const step=state.journey.step;
 if(step==='welcome')return '[data-action="tutorial-welcome"]';
 if(step==='worker')return state.modal==='castle-management'?'[data-action="buy-builder"]':'.builder-launch';
 if(['mine','house','barracks'].includes(step)){
  const product=step==='mine'?'build-mine':step==='barracks'?'build-garnison':'build-caserne-heros';
  return state.modal==='purchase'?'[data-action="purchase-confirm"]':state.modal==='shop'?'[data-action="buy"][data-id="'+product+'"]':'.shortcut.shop';
 }
 if(['mine-place','house-place','barracks-place'].includes(step))return '.grid-cell.available';
 if(['mine-finish','core-finish','house-finish','barracks-finish'].includes(step))return state.modal==='castle-management'?'[data-action="guide-speed"]':'.builder-launch';
 if(step==='collect')return '#selection [data-action="collect"]';
 if(step==='daily')return state.modal==='rewards'?'[data-action="claim"][data-id="calendar"]':'.event-card[data-page="rewards"]';
 if(step==='upgrade')return state.modal==='upgrade'?'[data-action="upgrade-confirm"]':state.selected==='building:core'?'#selection [data-action="upgrade"]':'.building[data-id="building:core"]';
 if(step==='garrison')return state.modal==='info'?'#modal [data-action="housing-assign"]':state.selected===state.journey.firstHouseId?'#selection [data-action="info"]':'.building[data-id="'+state.journey.firstHouseId+'"]';
 if(step==='recruit')return state.modal==='building-function'?'[data-action="guide-recruit021"]':state.selected===state.journey.firstBarracksId?'#selection [data-action="enter-building"]':'.building[data-id="'+state.journey.firstBarracksId+'"]';
 if(step==='recruit-wait')return '#modal [data-action="guide-recruit-observe021"]';
 if(step==='buttons')return '[data-action="guide-army"]';
 if(step==='army')return state.modal==='army'?'#modal-tabs [data-action="guide-campaign"]':'.shortcut.army';
 if(step==='campaign')return state.modal==='stage'?'#modal [data-action="battle"]':state.mapPage==='campaign'?'.journey-castle[data-stage="1"]':'.shortcut.campaign';
 if(step==='battle')return state.battle?.engine?.status==='running'?'.deploy-one':'#modal [data-action="guide-end"]';
 return null;
}
let guideFrame=0,guideAutoTarget=null;
function scheduleGuidePointer(){
 if(guideFrame)return;
 const request=typeof requestAnimationFrame==='function'?requestAnimationFrame:fn=>setTimeout(fn,0);
 guideFrame=request(()=>{guideFrame=0;refreshTutorialPointer();});
}
function rectIntersection(a,b){return Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left))*Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));}
function placeGuideCard(targetRect){
 const card=$('.guide-card');if(!card?.getBoundingClientRect)return;
 const width=card.classList.contains('guide-tiko326')?Math.min(310,innerWidth-24):Math.min(260,Math.max(190,innerWidth*.27));card.style.width=width+'px';
 const height=card.getBoundingClientRect().height||150,pad=12;
 const candidates=[[Math.max(pad,(innerWidth-width)/2),innerHeight-height-pad],[Math.max(pad,(innerWidth-width)/2),pad+48],[pad,pad],[innerWidth-width-pad,pad],[pad,innerHeight-height-pad],[innerWidth-width-pad,innerHeight-height-pad],[pad,Math.max(pad,(innerHeight-height)/2)],[innerWidth-width-pad,Math.max(pad,(innerHeight-height)/2)]];
 const modal=state.modal?$('#modal')?.getBoundingClientRect():null;
 const buttons=[...document.querySelectorAll('#modal button,#selection button,#hud>*,#hud button')].map(b=>b.getBoundingClientRect()).filter(b=>b.width&&b.height);
 let best=null;
 for(const [x,y]of candidates){
  const box={left:x,top:Math.max(pad,y),right:x+width,bottom:Math.max(pad,y)+height};
  let score=targetRect?rectIntersection(box,{left:targetRect.left-24,top:targetRect.top-24,right:targetRect.right+24,bottom:targetRect.bottom+24})*100:0;
  for(const b of buttons)score+=rectIntersection(box,b)*5;
  if(modal)score+=rectIntersection(box,modal)*.2;
  if(!best||score<best.score)best={...box,score};
 }
 if(best){card.style.left=best.left+'px';card.style.top=best.top+'px';}
}
function refreshTutorialPointer(){
 document.querySelector('.guide-arrow')?.remove();
 for(const el of document.querySelectorAll('.guide-target'))el.classList.remove('guide-target');
 if(!guideActive()){document.querySelector('.guide-card')?.remove();return;}
 const selector=guideTarget(),target=selector&&$(selector);
 if(!target||target.disabled||!target.getBoundingClientRect){placeGuideCard(null);return;}
 if(state.modal&&!$('#modal-layer').hidden&&target.closest('#modal-layer')===null&&!target.closest('.guide-card')){placeGuideCard(null);return;}
 const scroll=target.closest('#modal-body,.shop-products,.full-map-scroll');
 if(guideAutoTarget!==target){
  guideAutoTarget=target;
  // Déplacer uniquement les scrollers du panneau, jamais la page du jeu.
  for(let parent=target.parentElement;parent&&parent!==document.body;parent=parent.parentElement){
   if(!parent.matches('#modal-body,.shop-products,.full-map-scroll'))continue;
   const a=target.getBoundingClientRect(),b=parent.getBoundingClientRect();
   const sy=b.height/(parent.clientHeight||b.height)||1,sx=b.width/(parent.clientWidth||b.width)||1;
   if(a.top<b.top+8)parent.scrollTop+=(a.top-b.top-12)/sy;
   else if(a.bottom>b.bottom-8)parent.scrollTop+=(a.bottom-b.bottom+12)/sy;
   if(a.left<b.left+8)parent.scrollLeft+=(a.left-b.left-12)/sx;
   else if(a.right>b.right-8)parent.scrollLeft+=(a.right-b.right+12)/sx;
  }
 }
 let box=target.getBoundingClientRect();if(!box.width||!box.height){placeGuideCard(null);return;}
 const clip=scroll?.getBoundingClientRect();if(clip&&(box.bottom<clip.top||box.top>clip.bottom)){placeGuideCard(null);return;}
 target.classList.add('guide-target');placeGuideCard(target.closest('.guide-card')?null:box);if(target.closest('.guide-card'))return;
 box=target.getBoundingClientRect();
 const size=42,arrow=document.createElement('div');arrow.className='guide-arrow';arrow.setAttribute('aria-hidden','true');
 arrow.dataset.target=selector;arrow.innerHTML='<svg viewBox="0 0 80 80"><path d="M26 7h28v30h17L40 72 9 37h17z" fill="#ffdb68" stroke="#82582c" stroke-width="4"/><path d="M31 13h18v30h12L40 64 20 43h11z" fill="#fff1a6"/></svg>';
 let x=box.left+box.width/2-size/2,y=box.top-size-4,rotation=0;
 if(y<8){y=box.bottom+4;rotation=180;}
 arrow.style.left=Math.max(6,Math.min(innerWidth-size-6,x))+'px';arrow.style.top=Math.max(6,Math.min(innerHeight-size-6,y))+'px';arrow.style.setProperty('--guide-angle',rotation+'deg');document.body.append(arrow);
}
