const refinementHUD=renderHUD,refinementModal=renderModal,refinementMap=renderFullMap;
const refinementDetail=structureDetail,refinementAction=action,refinementAppearance=applyAppearance;
const CASTLE_PRESENTATION={
 'skin-astral':{side:52,top:50,bottom:32},
 'skin-frost':{side:86,top:116,bottom:66},
 'skin-obsidian':{side:98,top:134,bottom:72},
 'skin-castillet':{side:168,top:175,bottom:92},
 ...Object.fromEntries(['terre','bois','braise','givre'].map(id=>['skin-campagne-'+id,{side:112,top:105,bottom:55}]))
};
function sceneAnchors(){
 const zone=$('#castle-zone'),castle=$('#castle'),center=zone.offsetLeft+zone.clientWidth/2;
 const fit=Number(castle.dataset.fit)||.85,feet=zone.offsetTop+zone.clientHeight+8*fit;
 const bg=state.previewCosmetic?.kind==='background'?state.previewCosmetic.id:state.cosmetics.background;
 const anchor=MODELS.SCENE_LAYOUTS?.[bg]?.platform||[.5,.735];
 const width=1760,height=width*900/1600;
 cameraLayer().style.setProperty('--scene-image-width',width+'px');
 cameraLayer().style.setProperty('--scene-image-height',height+'px');
 cameraLayer().style.setProperty('--scene-image-x',(center-width*anchor[0]+900)+'px');
 cameraLayer().style.setProperty('--scene-image-y',(feet-height*anchor[1]+900)+'px');
 castle.dataset.platformCenter=String(center);
 castle.dataset.platformFeet=String(feet);
}
fitCastle=function(){
 const zone=$('#castle-zone'),castle=$('#castle'),floors=layout.floors+Number(!state.battle&&state.jobs.some(j=>j.floorJob));
 const skin=castle.dataset.skin||state.cosmetics.skin,m=CASTLE_PRESENTATION[skin]||CASTLE_PRESENTATION['skin-astral'];
 const content=layout.slots*CW(),width=content+2*m.side,height=floors*fh()+m.top+m.bottom;
 const fit=Math.min(.85,Math.max(.25,((zone.clientWidth||1050)-24)/width),Math.max(.25,((zone.clientHeight||490)-18)/height));
 Object.assign(castle.style,{zoom:'',position:'absolute',width:width+'px',height:height+'px',left:((zone.clientWidth||1050)-width)/2+'px',top:'auto',bottom:'0',margin:'0',transform:'scale('+fit+')',transformOrigin:'50% 100%'});
 for(const [key,value]of Object.entries({'content-width':content+'px','floor-count':floors,'castle-side':m.side+'px','castle-top':m.top+'px','castle-bottom':m.bottom+'px'}))castle.style.setProperty('--'+key,value);
 castle.dataset.fit=String(fit);castle.dataset.presentation=skin;zone.scrollTop=zone.scrollLeft=0;
 applyCamera();sceneAnchors();
};
applyAppearance=function(){refinementAppearance();if($('#castle-zone'))sceneAnchors();};
manaMarkup=function(battle=false){
 const m=battle?(state.battle?.replay?state.battle.history.frames[state.battle.cursor]?.mana:state.battle?.engine?.mana):state.recovery.mana;
 if(!m?.capacity)return '';
 const amount=Math.max(0,Math.min(m.capacity,m.amount)),ratio=amount/m.capacity;
 const wait=Math.ceil((Math.min(m.capacity,Math.floor(amount+1e-9)+1)-amount)/PreviewGame.MANA_RULES.perSecond);
 const caption=battle?'':m.enabled===false?'En construction':amount>=m.capacity-1e-8?'Mana complet':'+1 dans '+exactTime(wait);
 const dots=Array.from({length:5},(_,i)=>'<i class="'+(ratio>i/5?'':'empty')+'"><em style="width:'+Math.max(0,Math.min(100,(ratio*5-i)*100))+'%"></em></i>').join('');
 return button('<span class="mana-bar-row">'+icon('mana-5')+'<b>'+Math.floor(amount)+'/'+m.capacity+'</b><span class="energy-dots mana-dots">'+dots+'</span><span class="mana-more">+</span></span>'+(caption?'<small class="mana-countdown">'+caption+'</small>':''),battle?'cast-dismiss':'mana-open','aria-label="Mana '+Math.floor(amount)+' sur '+m.capacity+'"','mana-panel '+(battle?'mana-combat':'mana-home'));
};
renderHUD=function(){
 refinementHUD();
 const worker=$('.builder-launch'),actions=$('.profile-actions');
 if(worker&&actions){actions.append(worker);worker.classList.add('top-builder');worker.setAttribute('aria-label','Constructeurs');}
 const mana=$('#hud .mana-panel'),stats=$('#hud .stats-left');if(mana&&stats)stats.append(mana);
 const lower=stats?(stats.offsetTop||96)+(stats.offsetHeight||180)+15:280;
 const mission=$('.mission-peek'),chat=$('.chat-launch');
 const missionVisible=mission&&!mission.classList.contains('guide-unavailable')&&window.getComputedStyle?.(mission)?.display!=='none';
 if(mission)mission.style.top=lower+'px';
 if(chat)chat.style.top=(lower+(missionVisible?(mission.offsetHeight||90)+15:0))+'px';
};
// Une seule vérification pour les conditions affichées, le « + » et le paiement.
function buildingUpgradeView(o){
 if(!o||o.hero||o.level>=20||o.type.startsWith('decor-'))return null;
 syncBuilderSlots();
 const q=constructionPrice(o.type,o.level),status=PreviewGame.buildingUpgradeStatus({type:o.type,level:o.level,mainLevel:state.level,levels:PreviewGame.buildingLevelContext(homeLayout.buildings)});
 const rows=[...status.rows];
 if(o.type==='core')for(const resource of ['gold','elixir']){
  const type=resource==='gold'?'reserve':'reservoir',store=homeLayout.buildings.find(b=>b.type===type),capacity=capFor(resource);
  rows.push({type,name:resource==='gold'?'Réserve d’or':'Réserve d’élixir',actual:store?.level||1,capacity,requiredCapacity:q[resource],met:capacity>=q[resource]});
 }
 let reason=null;try{upgradeCheck(o);}catch(e){reason=e.message;}
 if(o.underConstruction)reason='Ce bâtiment est déjà en chantier.';
 return {q,rows,allowed:!reason,reason,affordable:state.wallet.gold>=q.gold&&state.wallet.elixir>=q.elixir,free:Math.max(0,state.builders-PreviewGame.occupiedBuilders(state.jobs))};
}
function prerequisiteMarkup(o){
 const view=buildingUpgradeView(o);if(!view||o.underConstruction)return '';
 return '<section class="building-prerequisites" aria-label="Conditions d’évolution"><h3>Conditions · niveau '+(o.level+1)+'</h3><div class="prerequisite-grid">'+view.rows.map(r=>{
  const type=r.type==='research'?'academie':r.type;
  const detail=r.requiredCapacity!==undefined?'Niveau '+r.actual+' · capacité '+fmt(r.capacity)+' / '+fmt(r.requiredCapacity)+' requis':'Niveau '+r.actual+' <b>→ '+r.level+'</b>';
  return '<div class="prerequisite '+(r.met?'met':'missing')+'" data-required-type="'+type+'">'+art('building:'+type)+'<div><strong>'+esc(r.name)+'</strong><span>'+detail+'</span></div><b class="prerequisite-state" aria-label="'+(r.met?'Condition remplie':'Condition requise')+'">'+(r.met?'✓':'!')+'</b></div>';
 }).join('')+'</div>'+(view.rows.length?'':'<p class="no-building-prerequisite">Aucun autre bâtiment requis.</p>')+'<div class="builder-requirement '+(view.free?'met':'missing')+'">'+art('ui:builder')+'<span><b>'+view.free+' constructeur'+(view.free>1?'s':'')+' disponible'+(view.free>1?'s':'')+'</b> · 1 requis</span></div>'+(view.reason?'<p class="upgrade-blocker" role="status">'+esc(view.reason)+'</p>':'')+'</section>';
}
structureDetail=function(upgrade=false){
 const html=refinementDetail(upgrade),o=v06ViewedObject();
 const requirements=prerequisiteMarkup(o);if(!requirements)return html;
 const marker='<p class="settings-note">';return html.includes(marker)?html.replace(marker,requirements+marker):html+requirements;
};
