var replayDBPromise020,replayCache020,replayLast020,replayWarnings020,saveSerial020;
function replayDatabase020(){
 if(!window.indexedDB)return Promise.resolve(null);
 if(!replayDBPromise020)replayDBPromise020=new Promise((resolve,reject)=>{const q=window.indexedDB.open('blabox-local-replays',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('replays'))q.result.createObjectStore('replays',{keyPath:'id'});};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});return replayDBPromise020;
}
async function storeReplay020(id,frames,expiresAt){
 if(!frames?.length)return;replayCache020??=new Map();const previous=replayCache020.get(id);if(previous===frames.length)return;
 const db=await replayDatabase020();if(!db)return;const count=frames.length;replayCache020.set(id,count);
 try{let data=new TextEncoder().encode(JSON.stringify(frames)),encoding='json';if(typeof CompressionStream==='function'){data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());encoding='gzip';}
 await new Promise((resolve,reject)=>{const tx=db.transaction('replays','readwrite'),store=tx.objectStore('replays');store.put({id,data,encoding,expiresAt,count});const cursor=store.openCursor();cursor.onsuccess=()=>{const c=cursor.result;if(c){if(c.value.expiresAt<Date.now())c.delete();c.continue();}};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
 }catch(error){replayCache020.delete(id);if(!replayWarnings020){replayWarnings020=true;notifyGame('replay-storage','La partie est conservée ; le replay n’a pas pu être enregistré.','item:info');}}
}
async function loadReplay020(id){
 const db=await replayDatabase020();if(!db)return null;const row=await new Promise((resolve,reject)=>{const q=db.transaction('replays').objectStore('replays').get(id);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});if(!row||row.expiresAt<Date.now())return null;
 const bytes=row.encoding==='gzip'?await new Response(new Blob([row.data]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer():row.data;return JSON.parse(new TextDecoder().decode(bytes));
}
