function persistPreviewGame(key,payload){
 try{
  const histories=payload.state?.history||state.history||[];const lightHistory=PreviewGame.recentBattles025(histories).map(h=>{if(h.frames?.length)storeReplay020(h.id,h.frames,h.expiresAt).catch(()=>{});return {...h,frameCount:h.frames?.length||h.frameCount||0,frames:[]};});
  const statePayload={...payload.state,history:lightHistory,edit:null,pendingPlacement:null};
  const value={...payload,saveVersion:3,saveSerial:(saveSerial020=(saveSerial020||0)+1),savedAt:Date.now(),scene:payload.battle?'battle':'home',state:statePayload};
  const serialized=JSON.stringify(value);let failed=false;
  try{window.localStorage?.setItem(key,serialized);}catch{failed=true;}
  if(failed){
   // Only obsolete Blabox save slots are eligible, never another application’s data.
   const storage=window.localStorage,oldKeys=[];if(typeof storage?.key==='function')for(let i=0;i<storage.length;i++){const k=storage.key(i);if(/^blabox-preview-(current|onboarding)-/.test(k)&&k!==key&&k!==key+'.backup'&&!k.endsWith(PLAYER_PREVIEW.releaseId)&&!k.endsWith(PLAYER_PREVIEW.previousReleaseId))oldKeys.push(k);}
   for(const old of oldKeys)storage.removeItem(old);storage?.setItem(key,serialized);
  }
  state.saveStatus='ok';state.guideSaveWarned=false;
 }catch(error){state.saveStatus='error';if(!state.guideSaveWarned){state.guideSaveWarned=true;toast('Enregistrement impossible. Exporte ta sauvegarde depuis les paramètres avant de fermer.');}}
}
