addCastleSignals=function(){
 const castle=$('#castle');if(!castle)return;castle.querySelector('.castle-signals')?.remove();
 for(const e of castle.querySelectorAll('.building .ready,.building .upgrade-plus,.building .collect-bubble'))e.remove();
 if(state.battle||state.visiting||state.edit)return;settleMines();
 const layer=document.createElement('div');layer.className='castle-signals';layer.setAttribute('aria-label','Actions rapides');
 const bounds=castle.getBoundingClientRect(),sx=bounds.width/(castle.offsetWidth||1),sy=bounds.height/(castle.offsetHeight||1);if(!sx||!sy)return;
 for(const o of [...homeLayout.buildings,...homeLayout.defenses,...homeLayout.barricades,...homeLayout.traps,...homeLayout.decorations]){
  const element=castle.querySelector('.building[data-id="'+o.id+'"]');if(!element)continue;const r=element.getBoundingClientRect(),x=(r.right-bounds.left)/sx-4,y=(r.top-bounds.top)/sy-5;
  const harvest=['mine','extracteur'].includes(o.type)&&!o.underConstruction&&(o.stored||0)>=mineCapacity(o)*.85;
  if(upgradeAvailable(o))layer.insertAdjacentHTML('beforeend',button('+','upgrade','data-id="'+o.id+'" aria-label="Évolution de '+esc(meta(o).name)+'" style="--signal-x:'+(x-(harvest?47:0))+'px;--signal-y:'+y+'px"','upgrade-plus world-signal'));
  if(harvest)layer.insertAdjacentHTML('beforeend',button(icon(o.type==='mine'?'gold':'elixir'),'collect','data-id="'+o.id+'" aria-label="Récolter '+fmt(collectAmount(o))+'" style="--signal-x:'+x+'px;--signal-y:'+y+'px"','collect-bubble world-signal'));
 }
 castle.append(layer);
};

