 if(s.index<s.targets.length-1){s.index++;showOpponent021();return;}
 const price=PreviewGame.pvpSearchPrice(state.level);enforceTestModes021();if(!initial&&(state.wallet.gold<price.gold||state.wallet.elixir<price.elixir))throw Error('Ressources insuffisantes pour une nouvelle recherche.');
