refreshDeployment=function(){
 const b=state.battle;if(!b?.engine?.manualDeployment||b.replay)return;
 const options=deploymentOptions();if(!options.some(o=>o.key===b.deploySelection&&o.count))b.deploySelection=options.find(o=>o.count)?.key||null;
 const key=JSON.stringify([b.engine.id,b.engine.started,b.deploySelection,options.map(o=>[o.key,o.count])]);let node=$('.deployment-bar');
 if(!node){$('#battle-hud').insertAdjacentHTML('beforeend',deploymentPanel());node=$('.deployment-bar');}
 else if(node===deploymentNode021&&key!==deploymentKey021){node.outerHTML=deploymentPanel();node=$('.deployment-bar');}
 deploymentNode021=node;deploymentKey021=key;
 for(const element of document.querySelectorAll('.spell-button')){
  const [id,slot]=element.dataset.id.split('-'),unit=b.engine.units.find(u=>u.hero===id),used=Boolean(unit?.usedSpells.includes(Number(slot)));
  element.disabled=!unit?.deployed||unit.hp<=0||b.engine.time<unit.spawnAt||used;element.classList.toggle('used',used);
 }
 const label=$('#battle-status'),text=!b.engine.started?'Le chronomètre démarre à ta première unité.':'Ciblage du plus proche · Portes : 0,3 s';if(label&&label.textContent!==text)label.textContent=text;
};
