const settingsBefore022=settings;
settings=function(){return '<section class="paper-card visual-test-panel"><h3>Tester les bâtiments · niveaux 1 à 20</h3><label>Niveau du Cœur et des structures<select id="visual-level-022"><option value="">Choisir un niveau</option>'+Array.from({length:20},(_,i)=>'<option value="'+(i+1)+'" '+(showcaseLevel022===i+1?'selected':'')+'>Niveau '+(i+1)+'</option>').join('')+'</select></label><p>Château de présentation avec tous les exemplaires débloqués. Ta partie est conservée.</p>'+(showcaseBackup022?button('Revenir à ma partie','visual-exit022','','secondary'):'')+'</section>'+settingsBefore022();};
