saveCurrentProgress=function(){if(!showcaseBackup022)return saveBefore022();};
saveJourney=function(){if(!showcaseBackup022)return journeySaveBefore022();};
function enterShowcase022(n){
 if(state.battle||state.visiting||state.opponentSearch021)throw Error('Reviens à ton château avant de tester les niveaux.');
 const scene=PreviewGame.visualShowcase(n,{clan:Boolean(state.clan)});
 if(!showcaseBackup022)showcaseBackup022={state:structuredClone(state),layout:structuredClone(homeLayout)};
 showcaseLevel022=n;for(const key of Object.keys(homeLayout))delete homeLayout[key];Object.assign(homeLayout,scene.layout);layout=homeLayout;
 state.level=n;state.journey={version:2,done:true,step:'done',events:[]};state.jobs=[];state.research=null;state.recruitment=[];state.selected=null;state.edit=null;state.battle=null;state.mapPage=null;state.troops=0;state.roster=[];state.formation=[];state.wallet.gold=capFor('gold');state.wallet.elixir=capFor('elixir');state.wallet.diamonds=50000;
 close(true);navStack.length=0;resetCamera();renderCastle();renderHUD();
 toast('Niveau '+n+' · '+scene.total+' structures disponibles');
}
function exitShowcase022(){if(!showcaseBackup022)return;const saved=showcaseBackup022;showcaseBackup022=null;showcaseLevel022=null;Object.assign(state,saved.state);for(const key of Object.keys(homeLayout))delete homeLayout[key];Object.assign(homeLayout,saved.layout);layout=homeLayout;state.modal=null;state.selected=null;state.edit=null;close(true);resetCamera();renderCastle();renderHUD();}
