document.addEventListener('change',e=>{if(e.target.id==='visual-level-022'&&e.target.value){try{enterShowcase022(Number(e.target.value));}catch(error){toast(error.message);}}});
const hudBefore022=renderHUD;renderHUD=function(){hudBefore022();$('#visual-banner022')?.remove();if(showcaseLevel022){const el=document.createElement('div');el.id='visual-banner022';el.innerHTML='<b>APERÇU · NIVEAU '+showcaseLevel022+'</b>'+button('Changer de niveau','open','data-page="settings"','secondary')+button('Revenir à ma partie','visual-exit022','','secondary');$('#stage').append(el);}};
function fitLevelSprites022(){
 for(const el of document.querySelectorAll('#castle .building:not(.trap):not(.housed-hero)')){
  const img=el.querySelector('img.structure-art'),o=object(el.dataset.id);if(!img||!o)continue;
  const id=meta(o)?.asset,config=MODELS.BUILDING_LEVEL_META[id];if(!config)continue;
  const imageId=config.aliasOf||id;const src=ART[imageId+':n'+String(o.level).padStart(2,'0')];if(src&&img.getAttribute('src')!==src)img.src=src;
  const width=meta(o).width*CW(),scale=Math.min(width/config.contentWidth,(fh()-16)/config.contentHeight),w=config.width*scale,h=config.height*scale,pad=config.footPads?.[o.level-1]??config.footPad??12;
  img.dataset.fxKey=config.key;img.dataset.fxLevel=o.level;img.classList.add('level-sprite022');
  Object.assign(img.style,{position:'absolute',width:w+'px',height:h+'px',left:(width-w)/2+'px',top:'auto',bottom:(-pad*scale)+'px',maxWidth:'none',maxHeight:'none',objectFit:'fill',transform:'none'});
  el.querySelector('.crossbow-turret')?.remove();
 }
}
