// Un seul canvas, 30 images/s maximum, aucune animation dans les onglets masqués.
let canvas022=null,paint022=null,lastFX022=0;
const ambient023=makeAmbientScheduler023();
function effectsFrame022(ms){
 if(typeof requestAnimationFrame==='function')requestAnimationFrame(effectsFrame022);if(ms-lastFX022<33||document.hidden)return;lastFX022=ms;
 const stage=$('#stage');if(!stage)return;
 if(!canvas022){canvas022=document.createElement('canvas');canvas022.id='building-fx022';canvas022.setAttribute('aria-hidden','true');stage.append(canvas022);paint022=makeBuildingFX022(canvas022.getContext('2d'));}
 const ctx=canvas022.getContext('2d'),bounds=stage.getBoundingClientRect(),scale=bounds.width/1600,h=stage.clientHeight;
 if(canvas022.width!==1600||canvas022.height!==h){canvas022.width=1600;canvas022.height=h;}
 ctx.clearRect(0,0,1600,h);if(!state.particles||state.fluentMode023||state.modal||state.battle){ambient023.reset();return;}
 const candidates=[];
 for(const img of document.querySelectorAll('#castle img.level-sprite022')){
  const host=img.closest('.building');if(host?.classList.contains('under-construction')||host?.classList.contains('ruined'))continue;
  const rect=img.getBoundingClientRect();if(rect.bottom<bounds.top||rect.top>bounds.bottom||rect.right<bounds.left||rect.left>bounds.right)continue;
  const profile=MODELS.BUILDING_FX.profiles[img.dataset.fxKey+':'+img.dataset.fxLevel]||[];
  const lay={x:(rect.left-bounds.left)/scale,y:(rect.top-bounds.top)/scale,w:rect.width/scale,h:rect.height/scale};
  for(const effect of profile)if(effect.enabled)candidates.push({key:host.dataset.id+':'+effect.id,effect,lay,infernal:img.dataset.fxKey==='infernal'});
 }
 ctx.save();ctx.beginPath();ctx.rect(0,0,1600,h);for(const button of document.querySelectorAll('#castle .world-signal,#castle .floor-door,#selection button')){const b=button.getBoundingClientRect();ctx.rect((b.left-bounds.left)/scale-3,(b.top-bounds.top)/scale-3,b.width/scale+6,b.height/scale+6);}ctx.clip('evenodd');
 for(const c of ambient023.select(candidates,ms/1000)){ctx.save();ctx.globalAlpha=c.alpha;paint022(c.effect,c.lay,ms/1000);ctx.restore();}
 ctx.restore();
}
if(typeof requestAnimationFrame==='function')requestAnimationFrame(effectsFrame022);
window.blaboxVisualTest={select:enterShowcase022,exit:exitShowcase022,inspect:()=>({level:showcaseLevel022,layout:structuredClone(layout),profiles:MODELS.BUILDING_FX.buildingCount})};

