function settleHeroes0291(now=Date.now()){let changed=false;for(const [id,j]of Object.entries(state.heroJobs0291)){if(j.endsAt>now)continue;if(!state.receipts0291.includes(j.id)){state.heroLevels[id]=Math.max(state.heroLevels[id]||1,j.to);state.receipts0291.push(j.id);notify0291('hero-complete:'+j.id,(heroes.find(h=>h.id===id)?.name||id)+' atteint le niveau '+j.to,'hero:'+id);}delete state.heroJobs0291[id];changed=true;}if(changed){syncGarrisons();saveCurrentProgress();renderCastle();renderHUD();if(state.modal==='hero')renderModal();}return changed;}
function speedHero0291(id,kind){let j=state.heroJobs0291[id];if(!j)return;let remaining=Math.max(0,j.endsAt-Date.now()),diamonds=RULES0291.acceleration(remaining);if(kind==='diamonds')ask0291('Terminer l’amélioration','<p>'+fmt(diamonds)+' diamants · '+exactTime(remaining/1000)+' restantes.</p>',()=>{if(state.wallet.diamonds<diamonds)return toast('Diamants insuffisants');state.wallet.diamonds-=diamonds;j.endsAt=Date.now();settleHeroes0291();saveCurrentProgress();});else{let options=Object.keys(state.inventory).filter(k=>k.startsWith('speed-')&&state.inventory[k]>0).map(k=>'<option value="'+k+'">'+k.replace('speed-','')+' s · stock '+state.inventory[k]+'</option>').join('');if(!options)return toast('Aucun accélérateur disponible.');ask0291('Utiliser un accélérateur','<select id="hero-speed-item0291">'+options+'</select>',()=>{let key=document.querySelector('#hero-speed-item0291')?.value||speedChoice0291;if(!key||!state.inventory[key])return toast('Objet indisponible');state.inventory[key]--;j.endsAt-=Number(key.slice(6))*1000;settleHeroes0291();saveCurrentProgress();renderModal();},{always:true});let select=document.querySelector('#hero-speed-item0291');speedChoice0291=select?.value;select?.addEventListener('change',()=>speedChoice0291=select.value);}}
let speedChoice0291=null;
function requestMonster0291(id,original,node){let level=state.monsterLevels[id],q=PreviewGame.v06ResearchQuote(level),a=PreviewGame.v06MonsterStats(id,level),b=PreviewGame.v06MonsterStats(id,level+1),paid=state.researchFunding?.id===id?state.researchFunding.paid:{gold:0,elixir:0},remaining={...q,gold:q.gold-paid.gold,elixir:q.elixir-paid.elixir};ask0291('Améliorer '+(MODELS.TROOPS.find(t=>t.id===id)?.name||id),pair0291({level,hp:a.hp,damage:a.damage,interval:a.attackInterval,image:monsterArt(id,level)},{level:level+1,hp:b.hp,damage:b.damage,interval:b.attackInterval,image:monsterArt(id,level+1)})+quoteHTML0291(remaining)+'<p>Le niveau change uniquement lorsque la recherche est terminée. Si les ressources sont insuffisantes, le financement partiel est conservé.</p>',()=>{actionBypass0291=true;try{original('research-fund',{id},node);saveCurrentProgress();}finally{actionBypass0291=false;}},{always:true});}
