PreviewGame.clanDonationQuote=RULES0291.donationQuote;PreviewGame.clanDonationAccelerationQuote=function(player,id,now=Date.now()){let remaining=PreviewGame.clanDonationWait(player,id,now);return {id,remaining,diamonds:RULES0291.acceleration(remaining)};};
PreviewGame.donateClanTechnology=function(player,clan,id,{commandId,now=Date.now()}={}){if(!player.id||player.clanId!==clan.id)throw Error('Rejoins ce clan.');let p=structuredClone(player),c=structuredClone(clan);if(c.ledger?.some(e=>e.id===commandId))return {player:p,clan:c,repeated:true};if(!commandId)throw Error('Transaction requise');if(PreviewGame.clanDonationWait(p,id,now))throw Error('Le prochain don n’est pas encore disponible.');let q=RULES0291.donationQuote(id,c.tech[id]||0,c.progress?.[id]||0);if(p.wallet[q.resource]<q.amount)throw Error('Ressources insuffisantes');p.wallet[q.resource]-=q.amount;p.wallet.diamonds+=PreviewGame.clanDonationDiamonds(id);p.clanDonationAt??={};p.clanDonationAt[id]=now;c.treasury[q.resource]+=q.amount;c.progress??={};if(!q.maxed){c.progress[id]=(c.progress[id]||0)+1;if(c.progress[id]>=q.target){c.tech[id]++;c.progress[id]=0;}}let e={id:commandId,kind:'donation',playerId:p.id,technology:id,resource:q.resource,amount:q.amount,at:now,week:PreviewGame.clanWeekKey(now),maxed:q.maxed};(c.donations??=[]).push(e);(c.ledger??=[]).push(e);return {player:p,clan:c};};
PreviewGame.accelerateClanDonation=function(player,clan,id,{commandId,now=Date.now()}={}){let p=structuredClone(player),c=structuredClone(clan);if(c.ledger?.some(e=>e.id===commandId))return {player:p,clan:c,repeated:true};if(p.clanId!==c.id)throw Error('Clan incorrect');let q=PreviewGame.clanDonationAccelerationQuote(p,id,now);if(!q.remaining)throw Error('Don déjà disponible');if(p.wallet.diamonds<q.diamonds)throw Error('Diamants insuffisants');p.wallet.diamonds-=q.diamonds;(p.clanDonationAt??={})[id]=now-PreviewGame.clanDonationCooldown(id);(c.ledger??=[]).push({id:commandId,kind:'donation-boost',playerId:p.id,technology:id,amount:q.diamonds,at:now});return {player:p,clan:c};};
function allianceLevel0291(){return Math.max(0,...homeLayout.buildings.filter(b=>['batiment-alliance','alliance','clan'].includes(b.type)&&!b.underConstruction).map(b=>b.level||0));}
function discounted0291(item){let rate=Math.min(.2,allianceLevel0291()*.01);return {...item,price:Math.floor(item.price*(1-rate)),secondaryPrice:Math.floor((item.secondaryPrice||0)*(1-rate)),discount:rate};}
const oldBuyClan0291=PreviewGame.buyClanShopItem;PreviewGame.buyClanShopItem=function(player,clan,id,opts){let item=PreviewGame.CLAN_SHOP_ITEMS.find(p=>p.id===id),price=discounted0291(item),extra={gold:0,elixir:0};extra[item.resource]+=item.price-price.price;if(item.secondaryResource)extra[item.secondaryResource]+=item.secondaryPrice-price.secondaryPrice;let p=structuredClone(player);for(let k of ['gold','elixir'])p.wallet[k]+=extra[k];let r=oldBuyClan0291(p,clan,id,opts);if(r.repeated)return {...r,player:structuredClone(player)};let ledger=r.clan.ledger.at(-1);ledger.discount=price.discount;ledger.paid=price.price;return r;};
clanTechPanel=function(){return treasuryHTML()+'<p>Prospérité et Maîtres bâtisseurs : 1 diamant par don, délai 1 h. Conseil et Réserve : 2 diamants, délai 2 h ; tarif double. Accélération : 5 diamants / h.</p><div class="card-grid">'+PreviewGame.CLAN_TECH_V06.map(t=>{let n=state.clanTech[t.id]||0,q=RULES0291.donationQuote(t.id,n,state.clanData.progress?.[t.id]||0),wait=donationWait(t.id);return '<article class="paper-card"><h3>'+t.name+'</h3><b>Niveau '+n+' / '+t.maxLevel+'</b><p>'+t.description+'</p>'+(q.maxed?'<p>Maximum atteint. Les dons suivants alimentent la trésorerie et le classement, sans progression.</p>':'<progress max="'+q.target+'" value="'+(state.clanData.progress[t.id]||0)+'"></progress><p>'+(state.clanData.progress[t.id]||0)+' / '+q.target+' dons</p>')+'<p>'+icon(q.resource)+fmt(q.amount)+' · +'+PreviewGame.clanDonationDiamonds(t.id)+' diamants</p>'+button(wait?'Disponible dans '+exactTime(wait/1000):'Donner','clan-donation','data-id="'+t.id+'" '+(wait?'disabled':''))+(wait?button('Accélérer · '+RULES0291.acceleration(wait)+' 💎','donation-boost-prepare','data-id="'+t.id+'"','secondary'):'')+'</article>';}).join('')+'</div>';};
clanShopPanel=function(){let stock=state.tab==='stock'&&officer(),items=stock?PreviewGame.CLAN_SHOP_ITEMS:PreviewGame.visibleClanShop(state.clanData);return treasuryHTML()+'<p>'+(stock?'Réapprovisionnement sans remise.':'Remise personnelle : '+allianceLevel0291()+' %. Seuls les articles en stock sont affichés.')+'</p>'+(officer()?button(stock?'Boutique des membres':'Gérer les stocks','tab','data-tab="'+(stock?'shop':'stock')+'"','secondary'):'')+'<div class="card-grid">'+items.map(p=>{let q=stock?p:discounted0291(p),n=state.clanData.stock[p.id]||0;return '<article class="paper-card unit-card">'+(p.id==='tiko'?heroArt('tiko'):art(p.asset))+'<h3>'+p.name+'</h3><p>Stock : '+n+'</p><p>'+icon(p.resource)+fmt(stock?p.wholesale:q.price)+(p.secondaryResource?' + '+icon(p.secondaryResource)+fmt(stock?p.secondaryWholesale:q.secondaryPrice):'')+'</p>'+button(stock?'Approvisionner':'Acheter',stock?'clan-restock-prepare':'clan-buy-prepare','data-id="'+p.id+'"')+'</article>';}).join('')+'</div>'+(items.length?'':'<p>Aucun article approvisionné.</p>');};
const oldAcceptClan0291=acceptClan;acceptClan=function(r){const oldTech={...state.clanTech};oldAcceptClan0291(r);for(const [id,h]of Object.entries(r.player.heroes||{}))if(h.unlocked){state.ownedHeroes.add(id);state.heroLevels[id]??=h.level||1;state.heroXP[id]??=0;}for(const [id,n]of Object.entries(r.clan.tech||{}))if(n>(oldTech[id]||0))notify0291('tech:'+r.clan.id+':'+id+':'+n,(PreviewGame.CLAN_TECH_V06.find(t=>t.id===id)?.name||id)+' atteint le niveau '+n,'item:gear');};
