function walletSearch030(){const spend=state.searchSpend030,age=spend?performance.now()-spend.started:10000;return '<div class="search-wallet030">'+['gold','elixir'].map(k=>{let amount=spend&&age<1550?Math.round(spend.before[k]-(spend.before[k]-spend.after[k])*Math.min(1,age/1500)):state.wallet[k];return '<div>'+icon(k)+'<span><small>Réserve · '+fmt(capFor(k))+'</small><b data-search-resource="'+k+'">'+fmt(amount)+'</b></span>'+(spend&&age<950?'<span class="search-spend030" style="animation-delay:-'+Math.min(1490,age)+'ms">−'+fmt(spend.price[k])+'</span>':'')+'</div>';}).join('')+'</div>';}
const searchRenderBefore030=renderSearch021;renderSearch021=function(){searchRenderBefore030();let root=$('#opponent-search-ui');if(root&&!root.hidden){root.querySelector('.search-wallet030')?.remove();root.insertAdjacentHTML('afterbegin',walletSearch030());}};
function animateSearchCost030(before,price){let after={...state.wallet},started=performance.now();state.searchSpend030={before,price,after,started};renderHUD();renderSearch021();function frame(t){let progress=Math.min(1,(t-started)/1500);for(let k of ['gold','elixir']){for(let el of document.querySelectorAll('[data-search-resource="'+k+'"]'))el.textContent=fmt(Math.round(before[k]-(before[k]-after[k])*progress));}if(progress<1)requestAnimationFrame(frame)}requestAnimationFrame(frame);setTimeout(()=>{state.searchSpend030=null;document.querySelectorAll('.search-spend030').forEach(e=>e.remove());},1550);}
nextOpponent021=async function(initial=false){const s=state.opponentSearch021;if(!s||s.loading&&!initial)return;if(s.index<s.targets.length-1){s.index++;showOpponent021();return;}const q=PreviewGame.pvpSearchPrice(state.level);if(!initial&&(state.wallet.gold<q.gold||state.wallet.elixir<q.elixir))throw Error('Ressources insuffisantes.');const token=++searchSequence021;s.loading=true;const prior={...state.wallet};let charged=false;try{await LOADING0291.run('Chargement',async r=>{if(state.opponentSearch021!==s||token!==searchSequence021)return;if(!initial&&!charged){state.wallet.gold-=q.gold;state.wallet.elixir-=q.elixir;charged=true;saveCurrentProgress();animateSearchCost030(prior,q);audioCue('resource.spend');}renderSearch021();const gate=document.querySelector('#loading0291');gate.querySelector('.search-wallet030')?.remove();gate.insertAdjacentHTML('beforeend',walletSearch030());r18ChooseTarget();const target=structuredClone(state.pvpTarget);await Promise.all([warmScene0291(target.layout,r,{battle:true}),new Promise(resolve=>setTimeout(resolve,charged?1500:0))]);if(state.opponentSearch021!==s||token!==searchSequence021)return;s.targets.push(target);if(s.targets.length>50)s.targets.shift();s.index=s.targets.length-1;showOpponent021();});document.querySelector('#loading0291 .search-wallet030')?.remove();saveCurrentProgress();}catch(e){if(charged){state.wallet.gold+=q.gold;state.wallet.elixir+=q.elixir;saveCurrentProgress();}s.loading=false;renderSearch021();throw e;}};
// La nouvelle scène est rendue derrière les portes fermées, avant leur ouverture.
beginBattle=async function(mode,index){if(transition0291)return;transition0291=true;let b=null;try{await LOADING0291.run('Chargement',async r=>{if(!b){let l=mode==='pvp'&&state.pvpTarget?.layout?state.pvpTarget.layout:mode==='campaign'?PreviewGame.stageMap(Math.max(0,(state.region||0)*8+(state.stage||1)-1),state.level):battleLayout();await warmScene0291(l,r,{battle:true});let pending=state.searchBattlePending021;try{if(mode==='pvp')state.searchBattlePending021=true;oldBegin0291(mode,index);}finally{state.searchBattlePending021=pending;}b=state.battle;if(!b)throw Error('Combat indisponible.');if(mode==='pvp')preparePillage0308(b);b.paused=true;applyVisual0291();await heroWarm024({units:b.engine.units,structures:b.engine.structures});b.heroAssetsReady024=true;renderBattleFrame(b.engine);renderBattleHUD();}});if(b&&state.battle===b){b.paused=false;renderBattleHUD();}}catch(e){toast(e.message)}finally{transition0291=false;}};
