// Production réelle : les montants affichés et calculés partagent le même barème.
function mineData030(o,owner=homeLayout,now=Date.now()){let base=PreviewGame.v06Production(o.level),b=PreviewGame.defenseHeroBonuses(owner,o),heroesBase=base*(1+(b.productionQuantity||0))*(1+(b.productionSpeed||0)),heroBonus=heroesBase-base,clanBonus=heroesBase*.02*(state.clanTech.yield||0),helpBonus=o.helpUntil>now?(heroesBase+clanBonus)*.2:0;return {base,heroBonus,clanBonus,helpBonus,total:o.underConstruction?0:heroesBase+clanBonus+helpBonus,capacity:mineCapacity(o),stored:Math.floor(o.stored||0),helper:o.helpedByName||null};}
settleMines=function(now=Date.now()){for(let o of homeLayout.buildings.filter(o=>['mine','extracteur'].includes(o.type))){o.stored??=state.journey?0:Math.round(mineCapacity(o)*.88);o.producedAt??=now;let d=mineData030(o,homeLayout,now);o.stored=Math.min(d.capacity,o.stored+Math.max(0,now-o.producedAt)/3600000*d.total);o.producedAt=now;}};
const helpBefore030=PreviewGame.helpMine;PreviewGame.helpMine=function(visitor,owner,id,opts){let r=helpBefore030(visitor,owner,id,opts);if(!r.repeated){let mine=r.owner.layout.buildings.find(m=>m.id===id);mine.helpedBy=visitor.id;mine.helpedByName=visitor.name||DEMOOPS0291.read().players.find(p=>p.id===visitor.id)?.name||state.members.find(p=>p.id===visitor.id)?.name||state.name;}return r;};
function minePanel030(o){let d=mineData030(o),kind=o.type==='mine'?'gold':'elixir';return '<section class="mine-summary030"><div class="mine-total030">'+icon(kind)+'<div><small>Production actuelle</small><strong>'+fmt(Math.round(d.total))+' / h</strong></div></div><div class="mine-storage030"><div><b>'+fmt(d.stored)+' / '+fmt(d.capacity)+'</b><small>Stockage de la mine</small></div><progress max="'+d.capacity+'" value="'+d.stored+'"></progress></div><div class="mine-bonuses030"><span>Base <b>'+fmt(Math.round(d.base))+' / h</b></span>'+(d.heroBonus?'<span>Héros <b>+'+fmt(Math.round(d.heroBonus))+' / h</b></span>':'')+'<span>Clan · niv. '+(state.clanTech.yield||0)+'<b>+'+fmt(Math.round(d.clanBonus))+' / h</b></span>'+(d.helpBonus?'<span>Aide · '+esc(d.helper||'Auteur non enregistré')+'<b>+'+fmt(Math.round(d.helpBonus))+' / h</b></span>':'')+'</div></section>';}
const structureBefore030=structureDetail;structureDetail=function(upgrade=false){let html=structureBefore030(upgrade),o=v06ViewedObject();if(o&&['mine','extracteur'].includes(o.type)){let box=document.createElement('div');box.innerHTML=html;let target=box.querySelector('.detail-copy')||box;let title=target.querySelector('h2');if(title)title.insertAdjacentHTML('afterend',minePanel030(o));else target.insertAdjacentHTML('afterbegin',minePanel030(o));return box.innerHTML;}return html;};
