profilePanel=function(){let selected=state.profile030.hero,used=state.profile030.changedDay===dailyKey(),p=state.photo;return '<section class="profile-heading030">'+(p.image?'<img class="profile-current030" src="'+esc(p.image)+'" alt="Portrait personnalisé">':heroArt(selected,'profile-current030'))+'<div><h2>'+esc(state.name)+'</h2><span>Cœur '+state.level+' · '+fmt(state.rating)+' de cote</span></div><img class="current-flag030" src="assets/drapeaux/'+state.flag+'.svg" alt="'+esc(state.flag)+'"></section><div class="section-top030"><h3>Portraits des héros</h3>'+button('ⓘ','info030','data-kind="portrait"','info-orb')+'</div><div class="portrait-status030">'+(used?'Prochain choix demain':cost030(0,0,1))+'</div><div class="portrait-grid030">'+heroes.map(h=>'<article class="portrait-card030 '+(h.id===selected?'selected':'')+'">'+heroArt(h.id)+'<b>'+esc(h.name)+'</b>'+button(h.id===selected&&!p.image?'Actuel':'Choisir','portrait030','data-id="'+h.id+'" '+(used||h.id===selected&&!p.image?'disabled':''),'secondary')+'</article>').join('')+'</div><h3>Drapeau</h3><div class="flag-grid030">'+countries030.map(([code,name])=>button('<img src="assets/drapeaux/'+code+'.svg" alt="'+name+'"><span>'+name+'</span>','flag030','data-id="'+code+'" aria-pressed="'+(state.flag===code)+'"',state.flag===code?'selected':'secondary')).join('')+'</div><section class="profile-personal030"><div class="section-top030"><h3>Image personnalisée</h3>'+button('ⓘ','info030','data-kind="photo"','info-orb')+'</div>'+(!p.entitled?button('Débloquer · 0,99 €','photo-unlock'):'<label class="photo-upload">Choisir une image<input type="file" id="profile-image" accept="image/png,image/jpeg,image/webp" '+(p.pending?'disabled':'')+'></label>')+(p.pending?'<p>Image en attente de validation.</p>':'')+'</section>';};
const hudBefore030=renderHUD;renderHUD=function(){hudBefore030();let avatar=$('#hud .avatar img');if(avatar){avatar.src=state.photo.image||ART['hero:'+state.profile030.hero];avatar.alt='Portrait de '+state.name;}let flag=$('#hud .flag');if(flag)flag.innerHTML='<img class="tiny-flag030" src="assets/drapeaux/'+state.flag+'.svg" alt="'+esc(state.flag)+'">';const performance=$('#quick-performance023');if(performance)performance.classList.toggle('combat-left030',Boolean(state.battle));decorateAds030();};
// Courriers détaillés : ouvrir, examiner tout le contenu puis récupérer.
function rewardName030(id){let names={'xp-small':'Potion · 150 XP','xp-medium':'Potion · 500 XP','xp-large':'Potion · 1 500 XP','health-25':'Vie · 25 %','health-50':'Vie · 50 %','health-100':'Vie · 100 %','mana-5':'Mana · +5','mana-10':'Mana · +10','mana-20':'Mana · +20','mana-40':'Mana · +40','energy-refill':'Recharge · 1 énergie','clan-banner':'Bannière du clan'};if(names[id])return names[id];if(id.startsWith('speed-'))return 'Accélérateur · '+exactTime(Number(id.slice(6)));return id;}
function rewardsMarkup030(reward={},extraXP=0,xpHero=null){let rows=[];for(let k of ['diamonds','gold','elixir'])if(reward[k])rows.push({name:{diamonds:'Diamants',gold:'Or',elixir:'Élixir'}[k],art:icon(k),n:reward[k]});for(let [id,n] of Object.entries(reward.items||{}))if(n)rows.push({name:rewardName030(id)+(id.startsWith('xp-')?' · droits cumulés':''),art:icon(ART['item:'+id]?id:id.startsWith('speed-')?'speed-3600':'gift'),n:id.startsWith('xp-')?n/4:n});for(let id of reward.heroes||[])rows.push({name:heroes.find(h=>h.id===id)?.name||id,art:heroArt(id),n:1});for(let id of reward.cosmetics||[])rows.push({name:MODELS.COSMETICS.find(c=>c.id===id)?.name||id,art:art(MODELS.COSMETICS.find(c=>c.id===id)?.asset||'cosmetic:'+id),n:1});if(extraXP)rows.push({name:'XP · '+(heroes.find(h=>h.id===xpHero)?.name||'Héros'),art:icon('xp-medium'),n:extraXP});return '<div class="reward-grid030">'+rows.map(r=>'<article>'+r.art+'<b>'+fmt(r.n)+'</b><span>'+esc(r.name)+'</span></article>').join('')+'</div>';}
function mailList030(){return '<div class="mail-list030">'+state.giftMails.map(m=>'<button class="mail-row030 '+(m.claimed?'claimed':'')+'" data-action="mail-open030" data-id="'+esc(m.id)+'">'+icon(m.claimed?'mail':'gift')+'<span><b>'+esc(m.title)+'</b><small>'+esc(m.text||'')+'</small></span><strong>'+(m.claimed?'Récupéré':'Ouvrir ›')+'</strong></button>').join('')+'</div>'+(state.giftMails.length?'':'<div class="empty030">Aucun cadeau pour le moment.</div>');}
