const shortHero030={tanuki:'Augmente le butin d’or et soutient les pilleurs.',tiko:'Un bâtisseur ingénieux qui aide au développement du château.',aegis:'Protège les alliés proches avec sa barrière.',aigle:'Repère et neutralise les pièges sur son passage.',chacal:'Un combattant rusé, efficace à distance.',drac:'Un dragon redoutable aux attaques enflammées.',elyra:'Soigne ses alliés et les aide à tenir le combat.',gargouille:'Une gardienne robuste qui protège le château.',gorvak:'Un guerrier solide qui renforce son équipe.',ignara:'Une combattante qui maîtrise les flammes.',jiangshi:'Un héros mystique qui affaiblit ses adversaires.',kryos:'Un spécialiste du gel qui ralentit les ennemis.',morghul:'Un mage puissant qui frappe ses adversaires à distance.',nian:'Un héros explosif qui sème le chaos.',nyra:'Une combattante agile qui soutient ses alliés.',tarasque:'Une défense vivante difficile à abattre.',tharos:'Un combattant robuste au service du château.',tortue:'Une protectrice qui aide ses alliés à résister.',valdorn:'Un héros puissant qui renforce son camp.',vexa:'Une héroïne rapide et précise.',brakk:'Un guerrier déterminé qui frappe avec force.'};
const detailHeroBefore030=heroDetail;heroDetail=function(){let box=document.createElement('div');box.innerHTML=detailHeroBefore030();let h=heroes.find(h=>h.id===state.heroId);if(!h)return box.innerHTML;let target=box.querySelector('.detail-copy')||box,mechanics=[h.desc||h.description||''];for(let e of box.querySelectorAll('.hero-effect-table')){mechanics.push([...e.querySelectorAll('tbody tr')].map(row=>row.textContent.replace(/→/g,' → ')).join('\n'));e.remove();}box.querySelectorAll('.bonus-cards,.bonus-card,.ability-pair').forEach(e=>e.remove());for(let p of box.querySelectorAll('p'))if(p.textContent.trim()===(h.desc||h.description||'').trim()||/frappe|pillage|garnison.*effet|bonus actif|passif|0,0|0\.0|chaque attaque/i.test(p.textContent))p.remove();state.heroMechanicsInfo030=mechanics.filter(Boolean).join('\n\n');let summary='<p class="hero-summary030">'+esc(shortHero030[h.id]||h.role)+'</p>',spells='<section class="hero-spells030"><div class="section-top030"><h3>'+(h.abilities?'Sort spécial':'Talent spécial')+'</h3>'+button('ⓘ','info030','data-kind="hero"','info-orb')+'</div>'+(spellNames[h.id].length?spellNames[h.id]:[h.passive]).map((name,i)=>'<article>'+(h.abilities?spellArt(h.id,i+1):heroArt(h.id))+'<b>'+esc(name)+'</b></article>').join('')+'</section>';let heading=target.querySelector('h2');if(heading)heading.insertAdjacentHTML('afterend',summary);else target.insertAdjacentHTML('afterbegin',summary);let stats=target.querySelector('.comparison-table');if(stats)stats.insertAdjacentHTML('afterend',spells);else target.insertAdjacentHTML('beforeend',spells);return box.innerHTML;};

// Promotions : deux offres exclusives, commutables uniquement pour les essais.
promotion0291=function(){let t=state.promoTest030;if(t){if(t.id==='none'||Date.now()>=t.until)return null;return {id:t.id,rate:t.id==='first'?.5:.2,until:t.until,demo:true};}if(state.level>=7&&!state.firstOfferAt0291&&Date.now()-state.accountCreated0291<=30*RULES030.DAY)state.firstOfferAt0291=Date.now();return RULES0291.activePromotion({firstOfferAt:state.firstOfferAt0291,purchaseCount:state.purchaseHistory.filter(p=>p.currency==='eur'&&p.status!=='refunded').length},Date.now());};
const productsBefore030=products;products=function(){let rows=productsBefore030().filter(p=>!['gold-fill','elixir-fill'].includes(p.id)&&!(p.resource&&(p.fraction||.5)===.5));return rows.map(p=>{let h=p.hero&&heroes.find(h=>h.id===p.hero);if(p.currency==='eur')return {...p,savingsPercent:0,description:'',rarity:null};if(h)return {...p,description:shortHero030[h.id]||h.role,rarity:h.tier};if(p.id==='xp-small')return {...p,name:'Potion XP · 150 XP',description:'',xp:150};return p;}).sort((a,b)=>a.hero&&b.hero?['Commun','Rare','Épique','Légendaire'].indexOf(a.rarity)-['Commun','Rare','Épique','Légendaire'].indexOf(b.rarity):0);};
function promoTimer030(){let p=promotion0291();return p?'<small class="deal-countdown030" data-promo-until="'+p.until+'">'+exactTime(Math.max(0,(p.until-Date.now())/1000))+'</small>':'';}
function deal030(p){const base=p.baseAmount||p.amount,bonus=(p.amount||0)-base;return '<div class="diamond-visual030">'+art(p.asset,'diamond-pack-image030')+(bonus?'<span class="deal-label030">+'+Math.round(bonus/base*100)+' %</span>':'')+'<div class="diamond-total030">'+(bonus?'<s>'+fmt(base)+'</s>':'')+'<strong>'+fmt(p.amount)+'</strong><span>diamants</span></div></div>'+(bonus?'<div class="deal-equation030">'+fmt(base)+' + '+fmt(bonus)+' offerts</div>'+promoTimer030():'');}
shop=function(){if(state.tab==='inventory')return inventory();let rows=products();return '<div class="shop-layout shop030"><nav class="shop-categories">'+shopCategories.map(([id,label,i])=>button(icon(i)+esc(label),'category','data-category="'+id+'"',id===state.category?'active':'')).join('')+'</nav><div class="shop-products"><div class="shop-grid030">'+rows.map(p=>'<article class="store-card030 '+(p.currency==='eur'?'diamond-card030':'')+(p.rarity?' rarity-'+['Commun','Rare','Épique','Légendaire'].indexOf(p.rarity):'')+'">'+(p.rarity?'<span class="rarity030">'+esc(p.rarity)+'</span>':'')+(p.currency==='eur'?deal030(p):art(p.asset,'store-art030'))+'<h3>'+esc(p.currency==='eur'?'Trésor de diamants':p.name)+'</h3>'+(p.hero?'<p class="hero-card-summary030">'+esc(p.description)+'</p>':'')+(p.ribbon?'<span class="adventurer-choice030">'+esc(p.ribbon)+'</span>':'')+(p.hero?button('Voir le héros','hero','data-id="'+p.hero+'"','secondary'):p.structure?button('i','catalog-info','data-type="'+p.structure+'"','info-orb'):'')+button(p.owned?'Possédé':p.currency==='eur'?Number(p.price).toFixed(2).replace('.',',')+' €':p.quote?costLine(p.quote):icon(p.currency)+fmt(p.price),'buy','data-id="'+p.id+'" '+(p.owned?'disabled':''),'primary'+(p.currency==='eur'?' gold':''))+'</article>').join('')+'</div></div></div>';};
