// Le téléphone est tenu avec son bord supérieur à droite (paysage secondaire).
function phone0303(){return matchMedia('(pointer:coarse)').matches;}
function playWidth0303(){return phone0303()?Math.max(innerWidth,innerHeight):innerWidth;}
function playHeight0303(){return phone0303()?Math.min(innerWidth,innerHeight):innerHeight;}
function logicalDelta0303(x,y){if(document.body.classList.contains('phone-portrait0303'))return {x:-y,y:x};if(document.body.classList.contains('phone-reverse0303'))return {x:-x,y:-y};return {x,y};}
function logicalPoint0303(x,y){if(document.body.classList.contains('phone-portrait0303'))return {x:innerHeight-y,y:x};if(document.body.classList.contains('phone-reverse0303'))return {x:innerWidth-x,y:innerHeight-y};return {x,y};}
function logicalRect0303(el){const r=el.getBoundingClientRect();if(document.body.classList.contains('phone-portrait0303'))return {left:innerHeight-r.bottom,right:innerHeight-r.top,top:r.left,bottom:r.right,width:r.height,height:r.width};if(document.body.classList.contains('phone-reverse0303'))return {left:innerWidth-r.right,right:innerWidth-r.left,top:innerHeight-r.bottom,bottom:innerHeight-r.top,width:r.width,height:r.height};return r;}
function orientPhone0303(){const mobile=phone0303(),portrait=mobile&&innerHeight>innerWidth,angle=screen.orientation?.angle??window.orientation??0;document.body.classList.toggle('phone-landscape0303',mobile);document.body.classList.toggle('phone-portrait0303',portrait);document.body.classList.toggle('phone-reverse0303',mobile&&!portrait&&angle===90);document.body.classList.toggle('phone-short0303',mobile&&playHeight0303()<450);document.documentElement.style.setProperty('--play-width0303',playWidth0303()+'px');document.documentElement.style.setProperty('--play-height0303',playHeight0303()+'px');resize();hudDensity0303();}
async function lockPhone0303(){if(phone0303()&&screen.orientation?.lock){try{await screen.orientation.lock('landscape-secondary');}catch{/* L’affichage orienté reste disponible sans verrouillage natif. */}}orientPhone0303();}
function startDemoFullscreen0303(){if(document.body.dataset.demo!=='true')return;const overlay=document.createElement('div');overlay.id='demo-fullscreen0303';overlay.innerHTML='<button type="button" id="demo-fullscreen-start0303"><span aria-hidden="true">⛶</span><strong>Plein écran</strong><small>Lancer la démo · haut du téléphone à droite</small></button>';document.body.append(overlay);overlay.querySelector('button').onclick=async()=>{overlay.remove();try{const root=document.documentElement;if(root.requestFullscreen)await root.requestFullscreen({navigationUI:'hide'});else if(root.webkitRequestFullscreen)root.webkitRequestFullscreen();}catch{/* Certains navigateurs mobiles n’exposent pas le plein écran. */}await lockPhone0303();};}
window.addEventListener('resize',orientPhone0303);screen.orientation?.addEventListener?.('change',orientPhone0303);document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)lockPhone0303();else orientPhone0303();});orientPhone0303();startDemoFullscreen0303();

