function settleOffers0304(){const now=Date.now();state.promotions0304=RULES0304.schedule(state.promotions0304,now);return RULES0304.active(state.promotions0304,now);}
function enqueueOffer0304(kind,key=kind,extra={}){state.promotions0304=RULES0304.enqueue(state.promotions0304,kind,key,Date.now(),extra);saveCurrentProgress();}
function migrateOffers0304(){if(state.promotions0304.migrated)return;state.promotions0304.migrated=true;const old=state.offerAfterPurchase0301;if(old?.startedAt){const o={kind:'first',key:'first',eligibleAt:old.startedAt,startedAt:old.startedAt,endsAt:old.startedAt+6*RULES0304.DAY,status:old.consumed?'purchased':Date.now()>=old.startedAt+6*RULES0304.DAY?'expired':'active'};state.promotions0304.offers.push(o);}state.promoTest030=null;}
