function naturalOffers0304(){const month=new Date().toISOString().slice(0,7),m=RULES0291.monthlyOffer(month);if(m.activeMonth&&Date.now()>=m.start&&Date.now()<m.end&&!state.promotions0304.offers.some(o=>o.key==='monthly:'+month)){state.promotions0304=RULES0304.enqueue(state.promotions0304,'monthly','monthly:'+month,Date.now());}return settleOffers0304();}
