decorateAds030=function(){const root=$('#hud .event-cards');if(!root)return;root.innerHTML=naturalOffers0304().map(o=>'<button class="mini-ad030 promo-ad0304 '+o.kind+'0304" data-action="offer-open0304" data-key="'+esc(o.key)+'" style="background-image:linear-gradient(90deg,#082b40ed,transparent),url(\''+offerArtwork0304(o)+'\')"><span>'+esc(offerConfig0304(o).title)+'<strong>'+esc(offerConfig0304(o).price?offerConfig0304(o).price.toFixed(2).replace('.',',')+' €':'+'+Math.round(offerConfig0304(o).rate*100)+' %')+'</strong>'+offerTimer0304(o)+'</span></button>').join('');};
function offerPanel0304(){const o=settleOffers0304().find(o=>o.key===state.offerKey0304);if(!o)return '<div class="empty030">Cette offre a expiré et ne reviendra plus.</div>';const c=offerConfig0304(o),reference=o.referenceMinor0304||Math.round((o.referenceDiamonds0304||0)*.99),ref=c.reference?Math.round(c.reference*100):reference,discount=ref&&c.price?Math.max(0,(1-Math.round(c.price*100)/ref)*100):null;return '<article class="offer-panel0304"><div class="offer-banner0304" style="background-image:linear-gradient(90deg,#082637e8,transparent 80%),url(\''+offerArtwork0304(o)+'\')"><h2>'+esc(c.title)+'</h2><b>'+esc(offerContent0304(o))+'</b>'+offerTimer0304(o)+'</div><div class="offer-details0304"><p>'+(o.kind==='monthly'?'Événement mensuel valable jusqu’à la fin du compte à rebours. Les bonus de diamants ne se cumulent pas : le meilleur bonus actif s’applique.':'Offre personnelle unique, utilisable une seule fois. À son expiration, elle sera définitivement perdue et ne reviendra jamais.')+'</p>'+(discount!==null?'<p class="offer-saving0304">'+(ref/100).toFixed(2).replace('.',',')+' € <span>→</span> <b>'+c.price.toFixed(2).replace('.',',')+' €</b> · économie de '+discount.toLocaleString('fr-FR',{maximumFractionDigits:2})+' %'+(o.kind==='builders'?'<small>Valeur séparée en diamants, convertie au tarif de base : 100 diamants = 0,99 €. Les ouvriers du lot sont supplémentaires.</small>':'')+'</p>':'')+'<div class="center-actions">'+button(c.price?'Continuer · '+c.price.toFixed(2).replace('.',',')+' €':'Voir les diamants',c.price?'offer-checkout0304':'offer-diamonds0304','data-key="'+esc(o.key)+'"')+'</div></div></article>';}
function offerCheckout0304(){const o=settleOffers0304().find(o=>o.key===state.offerKey0304);if(!o)return '<p>Offre expirée.</p>';const c=offerConfig0304(o);return '<article class="offer-checkout0304"><h2>'+esc(c.title)+'</h2><p>'+esc(offerContent0304(o))+'</p><strong>'+c.price.toFixed(2).replace('.',',')+' €</strong><p>Offre unique : après achat ou expiration, elle ne revient plus.</p><span class="demo-only0291">DÉMO · aucun paiement réel</span><div class="center-actions">'+button('Simuler l’achat pour le test','offer-pay0304','data-key="'+esc(o.key)+'"')+button('Retour','back','','secondary')+'</div></article>';}
function payOffer0304(key){if(sanctionsActives0291('purchases').length)throw Error('Achats suspendus.');const current=settleOffers0304().find(o=>o.key===key);if(!current)throw Error('Offre expirée ou déjà achetée.');const c=offerConfig0304(current);if(c.hero&&state.ownedHeroes.has(c.hero))throw Error('Ce héros est déjà dans ton équipe.');const next=RULES0304.buy(state.promotions0304,key),id=currentId('bundle'),at=Date.now(),db=DEMOOPS0291.read(),order={id,playerId:state.id,buyerName:state.name,kind:'bundle',offerKey:key,offerKind:current.kind,bundleName:c.title,paid:c.price.toFixed(2).replace('.',',')+' €',amountMinor:Math.round(c.price*100),baseDiamonds:0,totalDiamonds:0,status:'credited',verified:true,source:'Simulation locale',at,contents:{workers:c.workers||0,hero:c.hero||null,xpPotions:c.xp||0}};db.orders.push(order);DEMOOPS0291.write(db);state.promotions0304=next;state.commerce030.firstPurchase??={receipt:id,at};state.offerAfterPurchase0301.startedAt??=at;if(!state.promotions0304.offers.some(o=>o.key==='first'))state.promotions0304=RULES0304.enqueue(state.promotions0304,'first','first',at);if(c.workers)state.extraWorkers0304+=c.workers;if(c.hero){state.ownedHeroes.add(c.hero);state.heroLevels[c.hero]??=1;state.heroXP[c.hero]??=0;state.recovery.heroes[c.hero]={ratio:1,lastAt:at};}if(c.xp)state.vials.large=(state.vials.large||0)+c.xp;state.purchaseHistory.push({...order,currency:'eur',amount:0});state.giftMails.unshift({id:'bundle-receipt:'+id,kind:'bundle-receipt',playerId:state.id,title:'Ton achat · '+c.title,text:offerContent0304(current),claimed:true,remaining:{gold:0,elixir:0,diamonds:0,items:{},heroes:[],cosmetics:[]},order0304:order});syncBuilderSlots();saveCurrentProgress();renderHUD();open('inbox');toast('Lot attribué une seule fois · simulation locale.');}
