const mail0304=mailDetail030;mailDetail030=function(){const m=state.giftMails.find(m=>m.id===state.mailId030);if(m?.kind!=='bundle-receipt')return mail0304();const o=m.order0304;return '<article class="bundle-receipt0304"><h2>'+esc(m.title)+'</h2><p>'+esc(m.text)+'</p><dl class="receipt-facts0303"><div><dt>Acheteur</dt><dd>'+esc(o.buyerName)+'</dd></div><div><dt>Prix payé</dt><dd>'+esc(o.paid)+'</dd></div><div><dt>Date</dt><dd>'+new Date(o.at).toLocaleString('fr-FR')+'</dd></div></dl><p>Contenu déjà attribué à ton compte.</p>'+button('Retour au courrier','open','data-page="inbox"','secondary')+'</article>';};
function securityRegistry0304(){let db=DEMOOPS0291.read();const me=consoleSnapshot0291(),index=db.players.findIndex(p=>p.id===state.id);if(index>=0)db.players[index]={...db.players[index],...me};else db.players.push(me);db.referralCodes0304??={};for(const p of db.players)if(!db.referralCodes0304[p.id]){let value=RULES0304.code(p.id),n=1;while(Object.values(db.referralCodes0304).includes(value))value=RULES0304.code(p.id)+'-'+n++;db.referralCodes0304[p.id]=value;}DEMOOPS0291.write(db);return db;}
