function check31(){let today=dailyKey();if(p31.lastCheck===today)throw Error('Pointage déjà effectué aujourd’hui.');let yesterday=new Date(Date.now()-86400000).toLocaleDateString('en-CA',{timeZone:'Europe/Paris'});p31.streak=p31.lastCheck===yesterday?p31.streak+1:1;p31.vipXP+=P31.pointage(p31.streak);p31.lastCheck=today;save31();toast('Pointage enregistré · +'+P31.pointage(p31.streak)+' XP VIP');}
