function quantity317(t,qty,cap,unlocked){return '<div class="qty317">'+button('−','recruit-quantity','data-id="'+t.id+'" data-dir="-1" '+(!unlocked?'disabled':''),'secondary')+'<input id="recruit-qty-'+t.id+'" aria-label="Quantité de '+esc(t.name)+'" data-recruit-id="'+t.id+'" type="number" min="0" max="'+cap+'" value="'+qty+'" '+(!unlocked?'disabled':'')+'>'+button('+','recruit-quantity','data-id="'+t.id+'" data-dir="1" '+(!unlocked?'disabled':''),'secondary')+'</div>'}
recruitment316=function(){const cap=PreviewGame.v06ArmyCapacity(state.level),pending=state.recruitment.reduce((n,q)=>n+q.remaining,0),last=state.recruitment.at(-1),seconds=last?Math.max(0,(last.endsAt-Date.now())/1000):0;return '<section class="recruitment317"><header><b>'+state.troops+' prêts · '+pending+' en attente / '+cap+'</b>'+(last?'<span data-ends-at="'+last.endsAt+'">'+exactTime(seconds)+'</span>'+button('Terminer · '+Math.max(1,Math.ceil(seconds/60))+' '+icon('diamonds'),'finish-queue','','secondary')+button('Supprimer la file','queue-clear316','','danger-button'):'<span>File vide</span>')+'</header><div class="troop-grid317">'+MODELS.TROOPS.map(t=>{let unlocked=state.unlockedTroops.includes(t.id),qty=state.recruitChoices[t.id]||0,n=state.roster.find(r=>r.troop===t.id)?.count||0;return '<article class="recruit-card317 '+(!unlocked?'locked317':'')+'"><header><h3>'+esc(t.name)+'</h3><small>'+n+' prêts · niveau '+state.monsterLevels[t.id]+'</small></header><div class="troop-art317">'+monsterArt(t.id,state.monsterLevels[t.id])+'</div>'+quantity317(t,qty,cap,unlocked)+button(unlocked?'Recruter · '+fmt(PreviewGame.recruitUnitPrice(t.id)*qty)+' '+icon('elixir'):'Cœur '+t.unlock,'recruit','data-id="'+t.id+'" '+(!unlocked||!qty||state.troops+pending>=cap?'disabled':''),'primary recruit-submit317')+'</article>'}).join('')+'</div></section>'};recruitmentPanel=recruitment316;
guardPanel=function(h){let gs=(homeLayout.monsterGarrisons||[]).filter(g=>g.houseId===h.id),cap=PreviewGame.guardCapacity(h.level);return '<section class="guard-panel317"><div class="assigned-guards317">'+Array.from({length:cap},(_,i)=>{let g=gs[i];return '<article class="assigned-guard317 '+(!g?'empty':'')+'">'+(g?monsterArt(g.troop,g.level)+'<b>'+esc(MODELS.TROOPS.find(t=>t.id===g.troop)?.name||g.troop)+'</b>'+button('Retirer','guard-clear','data-id="'+g.id+'"','secondary'):'<b>Emplacement libre</b>')+'</article>'}).join('')+'</div><div class="troop-grid317 guard-stock317">'+MODELS.TROOPS.map(t=>{let n=state.roster.find(r=>r.troop===t.id)?.count||0;return '<article class="stock-card317">'+monsterArt(t.id,state.monsterLevels[t.id])+'<div><h3>'+esc(t.name)+'</h3><b>× '+n+'</b></div>'+button('Affecter','guard-assign','data-house="'+h.id+'" data-id="'+t.id+'" '+(!n||gs.length>=cap||h.underConstruction?'disabled':''),'secondary')+'</article>'}).join('')+'</div></section>'};
