function rewardDiff317(before,after){let rows=[];for(let k of ['gold','elixir','diamonds']){let n=(after.wallet[k]||0)+(after.pending[k]||0)-(before.wallet[k]||0)-(before.pending[k]||0);if(n>0)rows.push({name:{gold:'Or',elixir:'Élixir',diamonds:'Diamants'}[k],image:icon(k),n});}for(let scope of ['inventory'])for(let[k,v]of Object.entries(after[scope])){let n=v-(before[scope][k]||0);if(n>0){let id=scope==='vials'?'xp-'+k:k;rows.push({name:rewardName030(id),image:icon(id),n})}}for(let k of ['small','medium','large']){let n=(after.vials[k]||0)-(before.vials[k]||0)+((after.free[k]||0)-(before.free[k]||0))/4;if(n>0)rows.push({name:rewardName030('xp-'+k),image:icon('xp-'+k),n});}for(let id of after.heroes.filter(id=>!before.heroes.includes(id)))rows.push({name:heroName311(id),image:heroArt(id),n:1});for(let id of after.scrolls.filter(id=>!before.scrolls.includes(id)))rows.push({name:'Parchemin '+heroName311(id),image:scrollArt312(id),n:1});for(let id of after.cosmetics.filter(id=>!before.cosmetics.includes(id))){let c=MODELS.COSMETICS.find(c=>c.id===id);rows.push({name:c?.name||id,image:art(c?.asset||'cosmetic:'+id),n:1})}for(let[k,v]of Object.entries(after.xp)){let n=v-(before.xp[k]||0);if(n>0)rows.push({name:'XP · '+heroName311(k),image:heroArt(k),n});}return rows}
